    'assets/screens/standby.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The bomb waits to be armed. Data: arm (the attacking team), progress (0-1\n# while the attackers hold their button; the bar fills, letting go empties it).\ntemplate: standby\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: panel }\n    children:\n      - type: label\n        text: STANDBY\n        style: { font_size: 20, width: fill, align: center }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{progress && \'Arming... keep holding\' || \'Hold the button to arm\'}"\n    style: { font_size: 20, color: "{progress && \'white\' || \'muted\'}", visible: "{arm}" }\n  - type: label\n    text: Waiting\n    style: { font_size: 20, color: muted, visible: "{!arm}" }\n  - type: label\n    text: "{arm|upper}"\n    style: { font_size: 48, color: "{arm}", visible: "{arm}" }\n  - type: progress_bar\n    value: "{progress}"\n    style: { width: 220, height: 12, color: "{arm}", visible: "{arm}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: The bomb is not armed\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
