    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.domination\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nname: Domination\ndescription: The last team to claim the box scores while it holds it.\nroles:\n  zone: { requires: [team_input], optional: [team_display, audio, display] }\nparams:\n  capture_hold_ms: { type: int, min: 0, max: 60000, default: 3000, label: "Hold time to capture (ms)" }\n  tick_s:          { type: int, min: 1, max: 600,   default: 10,   label: "Seconds per scoring tick" }\n  points_per_tick: { type: int, min: 1, max: 1000,  default: 1,    label: "Points per tick" }\ni18n:\n  pt:\n    name: Domínio\n    description: A última equipa a capturar a caixa pontua enquanto a tiver.\n    params:\n      capture_hold_ms: Tempo a premir para capturar (ms)\n      tick_s: Segundos por intervalo de pontuação\n      points_per_tick: Pontos por intervalo\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Domination (draft): the last team to claim the box scores while it holds it.\n-- Screens (assets/screens/): standby until the first capture, then captured\n-- (the holding team, its points on this box and when it took it), and\n-- final_score when the game ends.\n\nlocal s = state.node { owner = nil, since = 0 }\n\nlocal function show()\n  if s.owner then\n    ui.screen("captured", { team = s.owner, points = score.get(s.owner), since = s.since })\n  else\n    ui.screen("standby", {})\n  end\nend\n\non("game.start", show)\n\non("team_input.hold", function(e)\n  if e.team == s.owner or e.ms < params.capture_hold_ms then\n    return\n  end\n  local previous = s.owner\n  s.owner = e.team\n  s.since = math.floor(game.time())\n  cap("team_display"):show(e.team)\n  audio.play("captured")\n  emit("zone.captured", { team = e.team, squad = e.squad, previous_team = previous })\n  show()\nend)\n\nevery(params.tick_s, function()\n  if s.owner then\n    score.add(s.owner, params.points_per_tick, "hold")\n    show()\n  end\nend)\n\n-- The core freezes scores on game.end; show the final result on the prop.\non("game.end", function()\n  ui.screen("final_score", { owner = s.owner, points = s.owner and score.get(s.owner) or nil })\nend)\n',
