        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The game is over. Data: owner (the team holding the zone at the end),\n# points (its points on this box).\ntemplate: final_score\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: panel }\n    children:\n      - type: label\n        text: GAME OVER\n        style: { font_size: 20, width: fill, align: center }\n  - type: spacer\n    height: fill\n  - type: label\n    text: The zone was held by\n    style: { font_size: 20, color: muted, visible: "{owner}" }\n  - type: label\n    text: "{owner|upper}"\n    style: { font_size: 48, color: "{owner}", visible: "{owner}" }\n  - type: label\n    text: "{points} points on this box"\n    style: { font_size: 20, visible: "{owner}" }\n  - type: label\n    text: No team held the zone\n    style: { font_size: 20, color: muted, visible: "{!owner}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Scores are final\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
    'assets/screens/standby.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# Nobody holds the zone yet. No data; the hold time comes from the game\'s parameters.\ntemplate: standby\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: panel }\n    children:\n      - type: label\n        text: ZONE\n        style: { font_size: 20, width: fill, align: center }\n  - type: spacer\n    height: fill\n  - type: label\n    text: HOLD TO CAPTURE\n    style: { font_size: 28, color: accent }\n  - type: label\n    text: "Hold your button for {params.capture_hold_ms / 1000} s"\n    style: { font_size: 20, color: muted }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Nobody holds this zone\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
  },
  'hacking_terminal': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.hacking_terminal\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nname: Hacking Terminal\ndescription: >-\n  A terminal with a puzzle on its keypad: crack a code from right-place and wrong-place counts, cut the\n  wires in the right order, or repeat a sequence. A wrong answer locks it for a while. Solving it can\n  reveal a code, score points and capture the terminal for the team that solved it; the puzzle comes\n  from the game\'s seed, so a replay sees the same one.\nroles:\n  terminal: { requires: [keypad], optional: [team_input, team_display, display, audio] }\nparams:\n  puzzle:      { type: string, default: code, max: 8, label: "Puzzle: code, wires or sequence" }\n  digits:      { type: int, min: 3, max: 6, default: 4, label: "Length: digits of the code, wires, keys of the sequence" }\n  lockout_s:   { type: int, min: 0, max: 600, default: 10, label: "Seconds the terminal locks after a wrong answer (0: no lock)" }\n  points:      { type: int, min: 0, max: 1000, default: 10, label: "Points for the team that solves it" }\n  reveal_code: { type: string, optional: true, max: 16, gm_only: true, label: "Code shown and sent when it is solved (empty: none)" }\n  capture:     { type: bool, default: false, label: "Solving captures the terminal; another team can hack it back" }\n  team:        { type: team, optional: true, label: "Team credited when nobody pressed a team button first (empty: none)" }\n  lang:        { type: string, default: pt, max: 2, label: "Language of the terminal\'s screen: pt or en" }\ncommands:\n  reset: { roles: [terminal], label: "New puzzle" }\ni18n:\n  pt:\n    name: Terminal de Hacking\n    description: >-\n      Um terminal com um enigma no teclado: descobrir um código pelos algarismos no sítio certo e fora do\n      sítio, cortar os fios pela ordem certa, ou repetir uma sequência. Uma resposta errada bloqueia-o\n      durante algum tempo. Resolvê-lo pode revelar um código, dar pontos e capturar o terminal para a\n      equipa que o resolveu; o enigma vem da semente do jogo, por isso uma repetição vê o mesmo.\n    params:\n      puzzle: "Enigma: code (código), wires (fios) ou sequence (sequência)"\n      digits: "Tamanho: algarismos do código, fios, teclas da sequência"\n      lockout_s: "Segundos de bloqueio depois de uma resposta errada (0: sem bloqueio)"\n      points: Pontos para a equipa que o resolve\n      reveal_code: "Código mostrado e enviado quando é resolvido (vazio: nenhum)"\n      capture: Resolver captura o terminal; outra equipa pode voltar a hackeá-lo\n      team: "Equipa creditada quando ninguém premiu primeiro um botão de equipa (vazio: nenhuma)"\n      lang: "Língua do ecrã do terminal: pt ou en"\n    commands:\n      reset: Novo enigma\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Hacking Terminal: a puzzle on the keypad (decision P4R5; modes/README.md).\n-- code: guess params.digits different digits, then #; the terminal counts\n-- the digits in place and elsewhere (* clears). wires: press the wires\'\n-- numbers in the right order. sequence: a key shows params.digits keys\n-- (1-9), one a second, then type them back (* shows them again). A wrong answer locks it for\n-- params.lockout_s (the wires join again, the sequence is shown again; the\n-- puzzle stays). Puzzles come from rand() (the game\'s seed and the node\'s id),\n-- so a replay gets the same ones. The solving team: the last to press its\n-- button since the last solve, else params.team. Solving\n-- emits hacking.solved, scores params.points and shows params.reveal_code;\n-- with params.capture the terminal becomes that team\'s (zone.captured) and,\n-- after the solved screen, sets a new puzzle for the other teams. The\n-- screens\' texts are in their templates, in params.lang (note: which line).\n\nlocal SOLVED_SHOW_S = 10\n\nlocal puzzle = ({ wires = "wires", sequence = "sequence" })[params.puzzle] or "code" -- or unknown\nlocal n = params.digits\n\nlocal owner, solved -- the team holding a captured terminal; solved, until a new puzzle\nlocal secret -- code: a string of digits; wires and sequence: a list of numbers\nlocal typed, history, tries = "", {}, 0 -- code: the guess, the last three { guess, right, close }\nlocal cut = {} -- wires: cut so far, in order\nlocal phase, step = "idle", 0 -- sequence: idle, show or input; the key shown or typed\nlocal locked_until, hacker, note\nlocal lock_t, tick_t, show_t, again_t = 0, 0, 0, 0 -- timers (cancel(0) does nothing)\n\nlocal function new_puzzle()\n  local list = {}\n  for i = 1, (puzzle == "code" and 10 or n) do\n    list[i] = puzzle == "code" and i - 1 or (puzzle == "wires" and i or rand(1, 9))\n  end\n  if puzzle ~= "sequence" then\n    for i = #list, 2, -1 do\n      local j = rand(1, i)\n      list[i], list[j] = list[j], list[i]\n    end\n  end\n  secret = puzzle == "code" and table.concat(list, "", 1, n) or list\n  typed, history, tries, cut, phase, step, note = "", {}, 0, {}, "idle", 0, nil\nend\n\nlocal function draw()\n  if solved then\n    return\n  end\n  local d = {\n    team = hacker or params.team,\n    owner = owner,\n    locked = locked_until and math.max(1, math.ceil(locked_until - game.time())) or 0,\n    note = note,\n  }\n  if puzzle == "code" then\n    d.typed = (typed .. string.rep("_", n - #typed)):gsub(".", "%0 "):sub(1, 2 * n - 1)\n    d.digits, d.tries, d.note = n, tries, note or "enter"\n    for i, h in ipairs(history) do\n      d["g" .. i], d["r" .. i], d["c" .. i] = h[1], h[2], h[3]\n    end\n    return ui.screen("hack_code", d)\n  end\n  d.of = n\n  if puzzle == "wires" then\n    local w = { 1, 2, 3, 4, 5, 6 }\n    for _, c in ipairs(cut) do\n      w[c] = "-"\n    end\n    d.wires, d.cut = table.concat(w, " ", 1, n), #cut\n    return ui.screen("hack_wires", d)\n  end\n  d.phase, d.step, d.key = phase, step, phase == "show" and secret[step] or nil\n  ui.screen("hack_sequence", d)\nend\n\nlocal function wrong()\n  audio.play("armed") -- the warning tone\n  cut, phase, step = {}, "idle", 0\n  cancel(show_t)\n  if params.lockout_s > 0 then\n    locked_until = game.time() + params.lockout_s\n    lock_t = after(params.lockout_s, function()\n      cancel(tick_t)\n      locked_until = nil\n      draw()\n    end)\n    tick_t = every(1, draw)\n  end\n  draw()\nend\n\nlocal function solve()\n  local team = hacker or params.team\n  cancel(show_t)\n  hacker = nil\n  audio.play("defused") -- the success tone\n  emit("hacking.solved", { team = team, puzzle = puzzle, code = params.reveal_code })\n  if team and params.points > 0 then\n    score.add(team, params.points, "hacking")\n  end\n  local capture = params.capture and team ~= nil\n  ui.screen("hack_solved", { team = team, code = params.reveal_code, capture = capture })\n  solved = true\n  if capture then\n    emit("zone.captured", { team = team, previous_team = owner })\n    owner = team\n    cap("team_display"):show(team)\n    new_puzzle()\n    again_t = after(SOLVED_SHOW_S, function()\n      solved = false\n      draw()\n    end)\n  end\nend\n\n-- The holder of a captured terminal cannot solve it again.\nlocal function mine()\n  if params.capture and owner and (hacker or params.team) == owner then\n    note = "yours"\n    return true\n  end\nend\n\nlocal keys = {}\n\nfunction keys.code(k)\n  if k == "*" then\n    typed = ""\n  elseif k:match("^%d\$") and #typed < n then\n    typed = typed .. k\n  elseif k == "#" and #typed < n then\n    note = "short"\n  elseif k == "#" then\n    local guess = typed\n    typed = ""\n    if mine() then\n      return draw()\n    end\n    tries = tries + 1\n    if guess == secret then\n      return solve()\n    end\n    local right, close, a, b = 0, 0, {}, {}\n    for i = 1, n do\n      local x, y = secret:sub(i, i), guess:sub(i, i)\n      if x == y then\n        right = right + 1\n      else\n        a[x], b[y] = (a[x] or 0) + 1, (b[y] or 0) + 1\n      end\n    end\n    for digit, count in pairs(b) do\n      close = close + math.min(count, a[digit] or 0)\n    end\n    table.insert(history, 1, { guess, right, close })\n    history[4] = nil\n    return wrong()\n  end\n  draw()\nend\n\nfunction keys.wires(k)\n  local w = k:match("^%d\$") and tonumber(k)\n  if not w or w < 1 or w > n then\n    return\n  end\n  for _, c in ipairs(cut) do\n    if c == w then\n      return\n    end\n  end\n  if mine() then\n    return draw()\n  elseif secret[#cut + 1] ~= w then\n    return wrong()\n  end\n  cut[#cut + 1] = w\n  if #cut == n then\n    return solve()\n  end\n  draw()\nend\n\nlocal function show_next()\n  step = step + 1\n  if step > n then\n    cancel(show_t)\n    phase, step = "input", 0\n  end\n  draw()\nend\n\nfunction keys.sequence(k)\n  if phase == "idle" or (phase == "input" and k == "*") then\n    if mine() then\n      return draw()\n    end\n    phase, step = "show", 0\n    show_t = every(1, show_next)\n    return show_next()\n  elseif phase ~= "input" or not k:match("^[1-9]\$") then\n    return\n  elseif secret[step + 1] ~= tonumber(k) then\n    return wrong()\n  end\n  step = step + 1\n  if step == n then\n    return solve()\n  end\n  draw()\nend\n\nlocal function stop_all()\n  cancel(lock_t)\n  cancel(tick_t)\n  cancel(show_t)\n  cancel(again_t)\nend\n\non("game.start", function()\n  new_puzzle()\n  draw()\nend)\n\non("team_input.press", function(e)\n  hacker = e.team\n  draw()\nend)\n\non("keypad.key", function(e)\n  if type(e.key) ~= "string" or solved or locked_until or not secret then\n    return\n  end\n  note = nil\n  keys[puzzle](e.key)\nend)\n\n-- The GM\'s "reset": a new puzzle, unlocked and unsolved; the holder stays.\non("cmd.mode", function(e)\n  if e.name == "reset" then\n    stop_all()\n    locked_until, hacker, solved = nil, nil, false\n    new_puzzle()\n    log("hacking_terminal: new puzzle")\n    draw()\n  end\nend)\n\n-- The GM\'s owner override, when solving captures the terminal.\non("cmd.set_owner", function(e)\n  local free = e.team == nil or e.team == "" or e.team == "none"\n  if not params.capture or e.team == owner or (free and owner == nil) then\n    return\n  elseif free then\n    emit("zone.neutralized", { previous_team = owner })\n  else\n    emit("zone.captured", { team = e.team, previous_team = owner })\n  end\n  owner = not free and e.team or nil\n  cap("team_display"):show(owner or "none")\n  draw()\nend)\n\non("game.end", function()\n  stop_all()\n  ui.screen("final_score", { owner = owner })\nend)\n',
    'assets/screens/hack_code.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The code puzzle. Data: team (the team at the keypad, if known), owner (the\n# team holding a captured terminal), typed (the digits typed, "_" for the\n# rest), digits, tries, g1-g3 / r1-r3 / c1-c3 (the last guesses, newest\n# first: the guess, digits in the right place, digits in the code but\n# elsewhere), locked (seconds left of a lock, 0 when open, shown at the\n# bottom instead of the note), note (the line at the bottom: enter, short\n# for a guess too short, yours when its holder types). Texts in params.lang (pt or en).\ntemplate: hack_code\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || owner || \'panel\'}" }\n    children:\n      - type: label\n        text: DECIFRA O CÓDIGO\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{params.lang != \'en\'}" }\n      - type: label\n        text: CRACK THE CODE\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{params.lang == \'en\'}" }\n  - type: label\n    text: "Terminal: {owner|upper}"\n    style:\n      font_size: 14\n      color: "{owner}"\n      visible: "{owner}"\n      padding: { top: 4 }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{typed}"\n    style: { font_size: 48, color: "{locked && \'muted\' || \'accent\'}" }\n  - type: label\n    text: "{g1}: {r1} no sítio, {c1} fora"\n    style: { font_size: 20, visible: "{g1 && params.lang != \'en\'}" }\n  - type: label\n    text: "{g1}: {r1} right, {c1} wrong place"\n    style: { font_size: 20, visible: "{g1 && params.lang == \'en\'}" }\n  - type: label\n    text: "{g2}: {r2} no sítio, {c2} fora"\n    style: { font_size: 14, color: muted, visible: "{g2 && params.lang != \'en\'}" }\n  - type: label\n    text: "{g2}: {r2} right, {c2} wrong place"\n    style: { font_size: 14, color: muted, visible: "{g2 && params.lang == \'en\'}" }\n  - type: label\n    text: "{g3}: {r3} no sítio, {c3} fora"\n    style: { font_size: 14, color: muted, visible: "{g3 && params.lang != \'en\'}" }\n  - type: label\n    text: "{g3}: {r3} right, {c3} wrong place"\n    style: { font_size: 14, color: muted, visible: "{g3 && params.lang == \'en\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "Marca {digits} algarismos e #"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{!locked && note == \'enter\' && params.lang != \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: "Type {digits} digits, then #"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{!locked && note == \'enter\' && params.lang == \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: "O código tem {digits} algarismos"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{!locked && note == \'short\' && params.lang != \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: "The code has {digits} digits"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{!locked && note == \'short\' && params.lang == \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: "O terminal já é da tua equipa"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{!locked && note == \'yours\' && params.lang != \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: "Your team holds this terminal"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{!locked && note == \'yours\' && params.lang == \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: "BLOQUEADO {locked} s"\n    style:\n      font_size: 20\n      color: danger\n      visible: "{locked && params.lang != \'en\'}"\n      padding: { bottom: 8 }\n  - type: label\n    text: "LOCKED {locked} s"\n    style:\n      font_size: 20\n      color: danger\n      visible: "{locked && params.lang == \'en\'}"\n      padding: { bottom: 8 }\n',
    'assets/screens/hack_sequence.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The sequence puzzle. Data: team (the team at the keypad, if known), owner\n# (the team holding a captured terminal), phase (idle: waiting for a key;\n# show: the sequence is shown; input: the player types it back), key (the key\n# shown), step (the key shown, or the keys typed back so far), of (the\n# sequence\'s length), locked (seconds left of a lock, 0 when open), note\n# (yours when the holder\'s team types). Texts in params.lang (pt or en).\ntemplate: hack_sequence\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || owner || \'panel\'}" }\n    children:\n      - type: label\n        text: REPETE A SEQUÊNCIA\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{params.lang != \'en\'}" }\n      - type: label\n        text: REPEAT THE SEQUENCE\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{params.lang == \'en\'}" }\n  - type: label\n    text: "Terminal: {owner|upper}"\n    style:\n      font_size: 14\n      color: "{owner}"\n      visible: "{owner}"\n      padding: { top: 4 }\n  - type: spacer\n    height: fill\n  # Showing the sequence: the key, and its place in it.\n  - type: label\n    text: "{key}"\n    style: { font_size: 48, color: accent, visible: "{phase == \'show\'}" }\n  - type: label\n    text: "{step} / {of}"\n    style: { font_size: 20, color: muted, visible: "{phase == \'show\'}" }\n  # Typing it back.\n  - type: label\n    text: A TUA VEZ\n    style: { font_size: 28, color: accent, visible: "{phase == \'input\' && params.lang != \'en\'}" }\n  - type: label\n    text: YOUR TURN\n    style: { font_size: 28, color: accent, visible: "{phase == \'input\' && params.lang == \'en\'}" }\n  - type: progress_bar\n    value: "{step / of}"\n    style: { width: 260, height: 12, color: "{team || \'accent\'}", visible: "{phase == \'input\'}" }\n  - type: label\n    text: "{step} de {of}"\n    style:\n      font_size: 20\n      visible: "{phase == \'input\' && params.lang != \'en\'}"\n      padding: { top: 6 }\n  - type: label\n    text: "{step} of {of}"\n    style:\n      font_size: 20\n      visible: "{phase == \'input\' && params.lang == \'en\'}"\n      padding: { top: 6 }\n  # Waiting, or locked.\n  - type: label\n    text: "{of} TECLAS"\n    style: { font_size: 28, visible: "{phase == \'idle\' && !locked && params.lang != \'en\'}" }\n  - type: label\n    text: "{of} KEYS"\n    style: { font_size: 28, visible: "{phase == \'idle\' && !locked && params.lang == \'en\'}" }\n  - type: label\n    text: "TECLA ERRADA: BLOQUEADO {locked} s"\n    style: { font_size: 20, color: danger, visible: "{locked && params.lang != \'en\'}" }\n  - type: label\n    text: "WRONG KEY: LOCKED {locked} s"\n    style: { font_size: 20, color: danger, visible: "{locked && params.lang == \'en\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: O terminal já é da tua equipa\n    style:\n      font_size: 14\n      color: muted\n      visible: "{note == \'yours\' && params.lang != \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: Your team holds this terminal\n    style:\n      font_size: 14\n      color: muted\n      visible: "{note == \'yours\' && params.lang == \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: Carrega numa tecla para ver a sequência\n    style:\n      font_size: 14\n      color: muted\n      visible: "{!note && phase == \'idle\' && !locked && params.lang != \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: Press a key to see the sequence\n    style:\n      font_size: 14\n      color: muted\n      visible: "{!note && phase == \'idle\' && !locked && params.lang == \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: Memoriza as teclas\n    style:\n      font_size: 14\n      color: muted\n      visible: "{phase == \'show\' && params.lang != \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: Remember the keys\n    style:\n      font_size: 14\n      color: muted\n      visible: "{phase == \'show\' && params.lang == \'en\'}"\n      padding: { bottom: 10 }\n',
    'assets/screens/hack_solved.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The puzzle is solved. Data: team (the team that solved it, if known), code\n# (the code it reveals, if the game set one), capture (true when the terminal\n# is now that team\'s and another team can hack it back). Texts in\n# params.lang (pt or en).\ntemplate: hack_solved\nstyle: { background: "{team || \'panel\'}" }\nlayout:\n  - type: icon\n    icon: ok\n    style: { font_size: 48, color: contrast }\n  - type: label\n    text: ACESSO CONCEDIDO\n    style: { font_size: 28, color: contrast, visible: "{params.lang != \'en\'}" }\n  - type: label\n    text: ACCESS GRANTED\n    style: { font_size: 28, color: contrast, visible: "{params.lang == \'en\'}" }\n  - type: label\n    text: "{team|upper}"\n    style: { font_size: 20, color: contrast, visible: "{team}" }\n  - type: label\n    text: Código\n    style:\n      font_size: 14\n      color: contrast\n      visible: "{code && params.lang != \'en\'}"\n      padding: { top: 8 }\n  - type: label\n    text: Code\n    style:\n      font_size: 14\n      color: contrast\n      visible: "{code && params.lang == \'en\'}"\n      padding: { top: 8 }\n  - type: label\n    text: "{code}"\n    style: { font_size: 48, color: contrast, visible: "{code}" }\n  - type: label\n    text: Outra equipa pode voltar a hackeá-lo\n    style: { font_size: 14, color: contrast, visible: "{capture && params.lang != \'en\'}", padding: 6 }\n  - type: label\n    text: Another team can hack it back\n    style: { font_size: 14, color: contrast, visible: "{capture && params.lang == \'en\'}", padding: 6 }\n',
    'assets/screens/hack_wires.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The wires puzzle. Data: team (the team at the keypad, if known), owner (the\n# team holding a captured terminal), wires (the wires\' numbers, "-" for the\n# ones cut), cut and of (wires cut, of all of them), locked (seconds left of a\n# lock, 0 when open), note (yours when the holder\'s team types). Texts in\n# params.lang (pt or en).\ntemplate: hack_wires\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || owner || \'panel\'}" }\n    children:\n      - type: label\n        text: CORTA OS FIOS\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{params.lang != \'en\'}" }\n      - type: label\n        text: CUT THE WIRES\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{params.lang == \'en\'}" }\n  - type: label\n    text: "Terminal: {owner|upper}"\n    style:\n      font_size: 14\n      color: "{owner}"\n      visible: "{owner}"\n      padding: { top: 4 }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{wires}"\n    style: { font_size: 48, color: "{locked && \'muted\' || \'accent\'}" }\n  - type: progress_bar\n    value: "{cut / of}"\n    style: { width: 260, height: 12, color: "{team || \'accent\'}" }\n  - type: label\n    text: "{cut} de {of} cortados"\n    style:\n      font_size: 20\n      visible: "{!locked && params.lang != \'en\'}"\n      padding: { top: 6 }\n  - type: label\n    text: "{cut} of {of} cut"\n    style:\n      font_size: 20\n      visible: "{!locked && params.lang == \'en\'}"\n      padding: { top: 6 }\n  - type: label\n    text: "FIO ERRADO: BLOQUEADO {locked} s"\n    style:\n      font_size: 20\n      color: danger\n      visible: "{locked && params.lang != \'en\'}"\n      padding: { top: 6 }\n  - type: label\n    text: "WRONG WIRE: LOCKED {locked} s"\n    style:\n      font_size: 20\n      color: danger\n      visible: "{locked && params.lang == \'en\'}"\n      padding: { top: 6 }\n  - type: spacer\n    height: fill\n  - type: label\n    text: O terminal já é da tua equipa\n    style:\n      font_size: 14\n      color: muted\n      visible: "{note == \'yours\' && params.lang != \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: Your team holds this terminal\n    style:\n      font_size: 14\n      color: muted\n      visible: "{note == \'yours\' && params.lang == \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: Carrega no número do fio a cortar\n    style:\n      font_size: 14\n      color: muted\n      visible: "{!note && params.lang != \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: Press the number of the wire to cut\n    style:\n      font_size: 14\n      color: muted\n      visible: "{!note && params.lang == \'en\'}"\n      padding: { bottom: 10 }\n',
  },
  'holdall': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.holdall\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nkind: mode\nname: Hold-All Domination\ndescription: Teams capture boxes as in Domination, but a team scores only while it holds every box at once.\nroles:\n  zone: { requires: [team_input], optional: [team_display, audio, display] }\nparams:\n  capture_hold_ms: { type: int, min: 0, max: 60000, default: 3000, label: "Hold time to capture (ms)" }\n  tick_s:          { type: int, min: 1, max: 600,   default: 10,   label: "Seconds per scoring tick while one team holds every box" }\n  points_per_tick: { type: int, min: 1, max: 1000,  default: 1,    label: "Points per tick" }\n  min_zones:       { type: int, min: 1, max: 64,    default: 2,    label: "Boxes in play before anyone can score" }\ni18n:\n  pt:\n    name: Domínio Total\n    description: As equipas capturam caixas como no Domínio, mas uma equipa só pontua enquanto tiver todas as caixas ao mesmo tempo.\n    params:\n      capture_hold_ms: Tempo a premir para capturar (ms)\n      tick_s: Segundos por ponto enquanto uma equipa tem todas as caixas\n      points_per_tick: Pontos por intervalo\n      min_zones: Caixas em jogo antes de alguém poder pontuar\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Hold-All Domination, on each box: a team captures the box by holding its\n-- input, as in Domination. The box does not score by itself: the field\n-- controller\'s field.lua scores a team only while it holds every box.\n\nlocal s = state.node { owner = nil }\n\nlocal function capture(team, squad)\n  emit("zone.captured", { team = team, squad = squad, previous_team = s.owner })\n  s.owner = team\n  cap("team_display"):show(team)\n  audio.play("captured")\nend\n\non("team_input.hold", function(e)\n  if e.team ~= s.owner and e.ms >= params.capture_hold_ms then\n    capture(e.team, e.squad)\n  end\nend)\n\n-- The GM\'s owner override from the console: a team, or none to free the box.\non("cmd.set_owner", function(e)\n  if e.team == s.owner then\n    return\n  end\n  if e.team == nil or e.team == "" or e.team == "none" then\n    emit("zone.neutralized", { previous_team = s.owner })\n    s.owner = nil\n    cap("team_display"):show("none")\n  else\n    capture(e.team)\n  end\nend)\n\non("game.end", function()\n  ui.screen("final_score", { owner = s.owner })\nend)\n',
    'field.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Hold-All Domination, on the field controller: while one team holds every\n-- zone box (and at least params.min_zones of them are in play), it scores\n-- params.points_per_tick every params.tick_s seconds. Box owners come from\n-- the boxes\' STATE reports, which can arrive a little after the capture\n-- event, so the check also runs every second.\n\nlocal fs = state.field { holder = nil }\nlocal tick\n\nlocal function zone_ids()\n  local ids = {}\n  for _, n in ipairs(field.nodes("zone")) do\n    ids[#ids + 1] = n.id\n  end\n  return ids\nend\n\nlocal function check()\n  local ids = zone_ids()\n  local team = nil\n  if #ids >= params.min_zones then\n    team = field.common_owner(ids)\n  end\n  if team == fs.holder then\n    return\n  end\n  if fs.holder ~= nil then\n    cancel(tick)\n    tick = nil\n    emit("holdall.scoring_stop", { team = fs.holder })\n  end\n  fs.holder = team\n  if team ~= nil then\n    emit("holdall.scoring_start", { team = team })\n    -- The first points come one full tick after the last box fell.\n    tick = every(params.tick_s, function()\n      score.add(team, params.points_per_tick, "holdall")\n    end)\n  end\nend\n\non("zone.captured", check)\non("zone.neutralized", check)\nevery(1, check)\n',
  },
  'kill_confirmed': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.kill_confirmed\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nkind: mode\nname: Kill Confirmed\ndescription: >-\n  Players carry signed NFC tags. A team presses its button at the station and scans the tags it\n  collected: an enemy\'s tag confirms the kill (points for the team, a penalty for the tag\'s team), a\n  teammate\'s tag denies it. Forged tags and tags from another game are refused.\nroles:\n  station: { requires: [nfc, team_input], optional: [display] }\nparams:\n  confirm_points: { type: int, min: 0, max: 100, default: 1, label: "Points for a confirmed kill" }\n  penalty_points: { type: int, min: 0, max: 100, default: 1, label: "Points the killed player\'s team loses" }\n  turn_in_s:      { type: int, min: 3, max: 120, default: 20, label: "Seconds to scan tags after pressing the team button" }\n  retag_after_s:  { type: int, min: 1, max: 3600, default: 60, label: "Seconds before the same player\'s tag counts again" }\ni18n:\n  pt:\n    name: Baixa Confirmada\n    description: >-\n      Cada participante leva uma etiqueta NFC assinada. Uma equipa carrega no seu botão na estação e lê as\n      etiquetas que recolheu: a etiqueta de alguém da equipa adversária confirma a baixa (pontos para a\n      equipa e penalização para a equipa da etiqueta); a de alguém da própria equipa nega-a. Etiquetas\n      falsificadas ou de outro jogo são recusadas.\n    params:\n      confirm_points: Pontos por baixa confirmada\n      penalty_points: Pontos que perde a equipa de quem foi abatido\n      turn_in_s: Segundos para ler etiquetas depois de carregar no botão da equipa\n      retag_after_s: Segundos até a etiqueta da mesma pessoa voltar a contar\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Kill Confirmed: players carry signed NFC tags (protocol/nfc-tag.md). A team\n-- presses its button at the station, then scans the tags it collected within\n-- turn_in_s seconds (each scan keeps the station open). An enemy\'s tag\n-- confirms the kill: confirm_points for the team, penalty_points off the\n-- tag\'s team. A teammate\'s tag denies the kill: no points. The same player\'s\n-- tag counts again only after retag_after_s. Forged tags, tags from another\n-- game and tags without a team are refused; the shell checks the signature\n-- with the game key and says why in nfc.tag\'s reason.\n\nlocal refused = {\n  unsigned = "Not a game tag",\n  no_game = "No game: join one first",\n  game = "Tag from another game",\n  mac = "Forged tag",\n  team = "Unknown team",\n  format = "Damaged tag",\n  version = "Unknown tag version",\n}\n\nlocal open_team -- the team turning in tags\nlocal closes_at = 0\nlocal closer\nlocal counted = {} -- player -> game time when their tag last counted\nlocal message, failed, fade\n\nlocal function show()\n  local data = { message = message, error = failed }\n  if open_team then\n    data.team = open_team\n    data.left = math.max(0, math.ceil(closes_at - game.time()))\n  end\n  ui.screen("tags", data)\nend\n\n-- A message under the station\'s state, cleared after 4 s.\nlocal function say(text, bad)\n  message, failed = text, bad\n  show()\n  if fade then\n    cancel(fade)\n    fade = nil\n  end\n  if text then\n    fade = after(4, function()\n      fade = nil\n      message, failed = nil, false\n      show()\n    end)\n  end\nend\n\nlocal function close()\n  open_team, closer = nil, nil\n  say(nil, false)\nend\n\nlocal function open(team)\n  open_team = team\n  closes_at = game.time() + params.turn_in_s\n  if closer then\n    cancel(closer)\n  end\n  closer = after(params.turn_in_s, close)\nend\n\non("game.start", show)\n\non("team_input.press", function(e)\n  open(e.team)\n  say("Scan your tags", false)\nend)\n\non("nfc.tag", function(e)\n  if not e.valid then\n    log("kill confirmed: tag " .. tostring(e.uid) .. " refused: " .. tostring(e.reason))\n    return say(refused[e.reason] or "Not a game tag", true)\n  end\n  if open_team == nil then\n    return say("Press your team\'s button first", true)\n  end\n  if e.team == nil then\n    return say("This tag has no team", true)\n  end\n  local last = counted[e.player]\n  if last and game.time() - last < params.retag_after_s then\n    return say("Tag already counted", true)\n  end\n  counted[e.player] = game.time()\n  open(open_team)\n  if e.team == open_team then\n    emit("kill.denied", { team = open_team, player = e.player, owner = e.team })\n    say("Kill denied: " .. e.player, false)\n  else\n    emit("kill.confirmed", { team = open_team, player = e.player, owner = e.team })\n    score.add(open_team, params.confirm_points, "kill")\n    score.add(e.team, -params.penalty_points, "killed")\n    say("Kill confirmed: " .. e.player, false)\n  end\nend)\n\n-- The time left to scan, once a second while the station is open.\nevery(1, function()\n  if open_team then\n    show()\n  end\nend)\n',
    'assets/screens/tags.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The Kill Confirmed station. Data: team (the team turning in tags, while the\n# station is open), left (seconds left to scan), message, error.\ntemplate: tags\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || \'panel\'}" }\n    children:\n      - type: label\n        text: KILL CONFIRMED\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{!team}" }\n      - type: label\n        text: "{team|upper}: SCAN TAGS"\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{team}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Press your button\n    style: { font_size: 28, visible: "{!team}" }\n  - type: label\n    text: then scan the tags\n    style: { font_size: 20, color: muted, visible: "{!team}" }\n  - type: label\n    text: "{left}"\n    style: { font_size: 48, color: team, visible: "{team}" }\n  - type: progress_bar\n    value: "{left / params.turn_in_s}"\n    style: { width: 240, height: 8, color: team, visible: "{team}" }\n  - type: label\n    text: "{message}"\n    style:\n      font_size: 20\n      width: 300\n      color: "{error && \'danger\' || \'accent\'}"\n      visible: "{message}"\n      padding: { top: 6 }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "Enemy tag: confirmed. Team tag: denied."\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
  },
  'laststand': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.laststand\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nkind: mode\nname: Last Stand\ndescription: The defenders start with every zone. Once they are down to their last zone, a countdown to defeat runs until they retake another one.\nroles:\n  zone: { requires: [team_input], optional: [team_display, audio, display] }\nparams:\n  capture_hold_ms: { type: int, min: 0, max: 60000, default: 3000, label: "Hold time to capture (ms)" }\n  attackers:       { type: team, default: red, label: "Attackers (win when the defenders fall)" }\n  defenders:       { type: team, default: blue, label: "Defenders (start with every zone)" }\n  countdown_s:     { type: int, min: 10, max: 3600, default: 120, label: "Countdown to defeat (s)" }\n  last_zones:      { type: int, min: 0, max: 63, default: 1, label: "The countdown runs while the defenders hold this many zones or fewer" }\n  min_zones:       { type: int, min: 1, max: 64, default: 2, label: "Zones in play before the countdown can run" }\n  reset:           { type: bool, default: true, label: "The countdown starts over after a retake (otherwise it carries on where it stopped)" }\n  end_game:        { type: bool, default: true, label: "End the game when the defenders fall" }\ni18n:\n  pt:\n    name: Último Elemento\n    description: Os defensores começam com todas as zonas. Quando ficam reduzidos à última zona, corre uma contagem para a derrota até reconquistarem outra.\n    params:\n      capture_hold_ms: Tempo a premir para capturar (ms)\n      attackers: Atacantes (ganham quando os defensores caem)\n      defenders: Defensores (começam com todas as zonas)\n      countdown_s: Contagem para a derrota (s)\n      last_zones: A contagem corre enquanto os defensores tiverem este número de zonas ou menos\n      min_zones: Zonas em jogo antes de a contagem poder correr\n      reset: A contagem recomeça do início após uma reconquista (senão continua de onde parou)\n      end_game: Terminar o jogo quando os defensores caem\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Last Stand, on each zone box: the defenders hold the box when the game\n-- starts; any team captures it by holding its input. The field controller\'s\n-- field.lua counts the defenders\' zones and runs the countdown to defeat.\n\nlocal s = state.node { owner = nil }\n\nlocal function capture(team, squad)\n  emit("zone.captured", { team = team, squad = squad, previous_team = s.owner })\n  s.owner = team\n  cap("team_display"):show(team)\n  audio.play("captured")\nend\n\non("game.start", function()\n  if s.owner == nil then\n    capture(params.defenders)\n  end\nend)\n\non("team_input.hold", function(e)\n  if e.team ~= s.owner and e.ms >= params.capture_hold_ms then\n    capture(e.team, e.squad)\n  end\nend)\n\n-- The GM\'s owner override from the console: a team, or none to free the box.\non("cmd.set_owner", function(e)\n  if e.team == s.owner then\n    return\n  end\n  if e.team == nil or e.team == "" or e.team == "none" then\n    emit("zone.neutralized", { previous_team = s.owner })\n    s.owner = nil\n    cap("team_display"):show("none")\n  else\n    capture(e.team)\n  end\nend)\n\non("game.end", function()\n  ui.screen("final_score", { owner = s.owner })\nend)\n',
    'field.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Last Stand, on the field controller. Once the defence is set up (the\n-- defenders have held more than params.last_zones zones, or 30 s have\n-- passed: box owners come from STATE reports, which can lag), a countdown of\n-- params.countdown_s seconds runs whenever they hold params.last_zones\n-- zones or fewer. Retaking a zone stops it; it starts over (params.reset)\n-- or carries on where it stopped. When it runs out the defenders are\n-- defeated, and with params.end_game the attackers win the game.\n\nlocal fs = state.field { held = 0, countdown = false, defeated = false }\nlocal ready = false -- the defence is set up\nlocal timer -- the defeat timer, while the countdown runs\nlocal left = params.countdown_s -- seconds the next countdown starts from\nlocal deadline = 0\n\nlocal function defeat()\n  timer = nil\n  fs.countdown = false\n  fs.defeated = true\n  emit("laststand.defeated", { team = params.defenders })\n  if params.end_game then\n    game.win(params.attackers)\n  end\nend\n\nlocal function check()\n  if fs.defeated then\n    return\n  end\n  local zones = field.nodes("zone")\n  local held = 0\n  for _, n in ipairs(zones) do\n    if field.owner(n.id) == params.defenders then\n      held = held + 1\n    end\n  end\n  if fs.held ~= held then\n    fs.held = held -- state.field changes reach the console, so write only changes\n  end\n  if held > params.last_zones or game.time() >= 30 then\n    ready = true\n  end\n  local danger = ready and #zones >= params.min_zones and held <= params.last_zones\n  if danger and timer == nil then\n    deadline = game.time() + left\n    timer = after(left, defeat)\n    fs.countdown = true\n    emit("laststand.countdown_start", { team = params.defenders, duration_s = math.ceil(left) })\n  elseif not danger and timer ~= nil then\n    cancel(timer)\n    timer = nil\n    fs.countdown = false\n    local remaining = deadline - game.time()\n    emit(\n      "laststand.countdown_cancel",\n      { team = params.defenders, duration_s = math.ceil(remaining) }\n    )\n    left = params.reset and params.countdown_s or math.max(remaining, 0.1)\n  end\nend\n\non("zone.captured", check)\non("zone.neutralized", check)\nevery(1, check)\n',
  },
  'master_satellites': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.master_satellites\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nname: Master and Satellites\ndescription: >-\n  Teams capture a master box and its satellites as in Domination. Only the master scores, and the\n  satellites its holder also holds raise its points; when the master changes hands, every satellite goes\n  back to neutral.\nroles:\n  master:    { requires: [team_input], optional: [team_display, audio, display] }\n  satellite: { requires: [team_input], optional: [team_display, audio, display] }\nparams:\n  capture_hold_ms:     { type: int, min: 0, max: 60000, default: 3000, label: "Hold time to capture (ms)" }\n  tick_s:              { type: int, min: 1, max: 600,   default: 10,   label: "Seconds per scoring tick while a team holds the master" }\n  points_per_tick:     { type: int, min: 1, max: 1000,  default: 2,    label: "Points per tick for the master alone" }\n  satellite_bonus_pct: { type: int, min: 0, max: 1000,  default: 50,   label: "Bonus per satellite held, in % of the master\'s points (rounded down)" }\n  min_satellites:      { type: int, min: 0, max: 63,    default: 0,    label: "Satellites the master\'s holder needs before the master scores" }\ni18n:\n  pt:\n    name: Mestre e Satélites\n    description: >-\n      As equipas capturam uma caixa mestre e os seus satélites como no Domínio. Só a mestre pontua, e os\n      satélites que a mesma equipa tiver aumentam os seus pontos; quando a mestre muda de mãos, todos os\n      satélites voltam a ficar neutros.\n    params:\n      capture_hold_ms: Tempo a premir para capturar (ms)\n      tick_s: Segundos por intervalo enquanto uma equipa tem a mestre\n      points_per_tick: Pontos por intervalo só pela mestre\n      satellite_bonus_pct: Bónus por satélite, em % dos pontos da mestre (arredondado para baixo)\n      min_satellites: Satélites de que a equipa da mestre precisa antes de a mestre pontuar\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Master and Satellites, on each box (the master and the satellites run the\n-- same script): a team captures the box by holding its input, as in\n-- Domination. Boxes do not score: the field controller\'s field.lua scores the\n-- master\'s holder, with a bonus for the satellites it holds too, and frees\n-- every satellite when the master changes hands. It also tells the master box\n-- how many satellites its holder has (the mode command "status"), so the\n-- master shows them; a box that was never told is a satellite, or a box\n-- picked from its own preset list, and shows only who holds it.\n-- Screens (assets/screens/): standby, captured, master_status; final_score at\n-- the end (the Field Box\'s built-in screen).\n\nlocal s = state.node { owner = nil, since = 0 }\nlocal master = nil -- the last status from the controller: { held, of, points }\n\nlocal function show()\n  if s.owner == nil then\n    ui.screen("standby", {})\n  elseif master then\n    ui.screen("master_status", {\n      team = s.owner,\n      since = s.since,\n      held = master.held,\n      of = master.of,\n      points = master.points,\n    })\n  else\n    ui.screen("captured", { team = s.owner, since = s.since })\n  end\nend\n\nlocal function capture(team, squad)\n  emit("zone.captured", { team = team, squad = squad, previous_team = s.owner })\n  s.owner = team\n  s.since = math.floor(game.time())\n  cap("team_display"):show(team)\n  audio.play("captured")\n  if master then\n    -- A new holder of the master starts with no satellites (they are freed);\n    -- the controller\'s next status confirms it.\n    master.held, master.points = 0, params.points_per_tick\n  end\n  show()\nend\n\non("game.start", show)\n\non("team_input.hold", function(e)\n  if e.team ~= s.owner and e.ms >= params.capture_hold_ms then\n    capture(e.team, e.squad)\n  end\nend)\n\n-- The GM\'s owner override from the console, and the controller freeing the\n-- satellites: a team, or none to free the box (a free box stays as it is).\non("cmd.set_owner", function(e)\n  local free = e.team == nil or e.team == "" or e.team == "none"\n  if e.team == s.owner or (free and s.owner == nil) then\n    return\n  end\n  if free then\n    emit("zone.neutralized", { previous_team = s.owner })\n    s.owner = nil\n    cap("team_display"):show("none")\n    show()\n  else\n    capture(e.team)\n  end\nend)\n\n-- From field.lua, to the master box only: its holder\'s satellites and points per tick.\non("cmd.mode", function(e)\n  if e.name ~= "status" or e.team ~= s.owner then\n    return\n  end\n  master = {\n    held = math.tointeger(e.held) or 0,\n    of = math.tointeger(e.of) or 0,\n    points = math.tointeger(e.points) or 0,\n  }\n  show()\nend)\n\non("game.end", function()\n  ui.screen("final_score", { owner = s.owner })\nend)\n',
    'field.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Master and Satellites, on the field controller: while a team holds the\n-- master box, it scores every params.tick_s seconds (the first points one\n-- full tick after the capture): params.points_per_tick, plus\n-- params.satellite_bonus_pct % of that for each satellite it holds too,\n-- rounded down (score.add takes whole points), and nothing while it holds\n-- fewer than params.min_satellites. When the master leaves a team\'s hands\n-- (to another team, or freed by the GM), every satellite is freed. Box owners\n-- come from the boxes\' STATE reports, which can arrive a little after the\n-- capture event, so the check also runs every second. A satellite that\n-- rebooted is freed at the next change of the master, as on the field.\n-- With more than one master box, the first one (the lowest node id) counts.\n\nlocal fs = state.field { master = nil, held = 0 }\nlocal tick\nlocal told -- the last status sent to the master box\n\nlocal function master_id()\n  local m = field.nodes("master")[1]\n  return m and m.id\nend\n\nlocal function satellites_of(team)\n  local held, of = 0, 0\n  for _, n in ipairs(field.nodes("satellite")) do\n    of = of + 1\n    if team ~= nil and field.owner(n.id) == team then\n      held = held + 1\n    end\n  end\n  return held, of\nend\n\nlocal function points(held)\n  if held < params.min_satellites then\n    return 0\n  end\n  return params.points_per_tick + params.points_per_tick * held * params.satellite_bonus_pct // 100\nend\n\nlocal function free_satellites()\n  for _, n in ipairs(field.nodes("satellite")) do\n    field.send(n.id, "set_owner", { team = "none" })\n  end\nend\n\nlocal function check()\n  local id = master_id()\n  local owner = id and field.owner(id)\n  if owner ~= fs.master then\n    if tick then\n      cancel(tick)\n      tick = nil\n    end\n    if fs.master ~= nil then\n      free_satellites()\n    end\n    fs.master = owner\n    told = nil\n    if owner ~= nil then\n      tick = every(params.tick_s, function()\n        local amount = points(satellites_of(owner))\n        if amount > 0 then\n          score.add(owner, amount, "master")\n        end\n      end)\n    end\n  end\n  local held, of = satellites_of(owner)\n  if fs.held ~= held then\n    fs.held = held -- state.field changes reach the console, so write only changes\n  end\n  if owner ~= nil then\n    local status = owner .. " " .. held .. " " .. of .. " " .. points(held)\n    if status ~= told then\n      told = status\n      field.send(\n        id,\n        "mode",\n        { name = "status", team = owner, held = held, of = of, points = points(held) }\n      )\n    end\n  end\nend\n\non("zone.captured", check)\non("zone.neutralized", check)\nevery(1, check)\n',
    'assets/screens/captured.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A team holds a satellite (or a box with no controller). Data: team, since\n# (game time of the capture, in seconds). Boxes do not score: the master does.\ntemplate: captured\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: team }\n    children:\n      - type: label\n        text: ZONE HELD\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{team|upper}"\n    style: { font_size: 48, color: team }\n  - type: label\n    text: "held since {since|clock}"\n    style: { font_size: 20, color: muted }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Hold your button to take it over\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
    'assets/screens/master_status.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A team holds the master. Data: team, since (game time of the capture, in\n# seconds), held and of (the satellites the team holds, of all of them) and\n# points (the master\'s points per tick with that bonus), from the controller.\ntemplate: master_status\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: team }\n    children:\n      - type: label\n        text: MASTER HELD\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{team|upper}"\n    style: { font_size: 48, color: team }\n  - type: label\n    text: "{held} of {of} satellites"\n    style: { font_size: 20 }\n  - type: label\n    text: "{points} points every {params.tick_s} s"\n    style: { font_size: 20, color: "{points > 0 && \'white\' || \'danger\'}" }\n  - type: label\n    text: "held since {since|clock}"\n    style: { font_size: 14, color: muted }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Hold your button to take it over\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
    'assets/screens/standby.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# Nobody holds the box (a master or a satellite). No data; the hold time comes\n# from the game\'s parameters.\ntemplate: standby\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: panel }\n    children:\n      - type: label\n        text: ZONE\n        style: { font_size: 20, width: fill, align: center }\n  - type: spacer\n    height: fill\n  - type: label\n    text: HOLD TO CAPTURE\n    style: { font_size: 28, color: accent }\n  - type: label\n    text: "Hold your button for {params.capture_hold_ms / 1000} s"\n    style: { font_size: 20, color: muted }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Nobody holds this zone\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
  },
  'medic': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.medic\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\n# A role package: added to any game (org.atalaia.domination+org.atalaia.medic), its role\n# brings medic kits to the field, and a node given that role runs this script alone.\nkind: role\nname: Medic Kit\ndescription: >-\n  A medic kit next to any game. A hit player scans their signed NFC tag and holds a button for a time\n  the organisers set, to be healed; letting go early cancels. The kit has a number of heals and shows\n  how many are left; each player can be healed a limited number of times per game, at every kit, and the\n  GM and the players see every heal. Forged tags, tags from another game and players of a team the kit\n  does not serve are refused, and the screen says why.\nroles:\n  medic: { requires: [nfc, team_input], optional: [display, audio] }\nparams:\n  heal_hold_s:          { type: int, min: 1, max: 120, default: 10, label: "Seconds a player holds the button to be healed" }\n  charges:              { type: int, min: 1, max: 999, default: 5, label: "Heals in the kit" }\n  max_heals_per_player: { type: int, min: 0, max: 100, default: 2, label: "Heals per player in the game, at every kit (0: no limit)" }\n  cooldown_s:           { type: int, min: 0, max: 3600, default: 0, label: "Seconds a player waits between two heals (0: no wait)" }\n  team:                 { type: team, optional: true, label: "Team the kit serves (empty: every team)" }\n  lang:                 { type: string, default: pt, max: 2, label: "Language of the kit\'s screen: pt or en" }\ncommands:\n  refill: { roles: [medic], label: "Refill the kit" }\ni18n:\n  pt:\n    name: Ligaduras\n    description: >-\n      Um kit de primeiros socorros ao lado de qualquer jogo. A pessoa atingida lê a sua etiqueta NFC\n      assinada e mantém premido um botão durante o tempo que a organização definir, para receber o\n      tratamento; largar antes do tempo cancela. O kit tem um número de ligaduras e mostra quantas restam;\n      cada pessoa pode receber um número limitado de tratamentos por jogo, em todos os kits, e a\n      organização e quem joga veem cada tratamento. Etiquetas falsificadas ou de outro jogo, e pessoas de\n      uma equipa que o kit não serve, são recusadas, e o ecrã diz porquê.\n    params:\n      heal_hold_s: Segundos a premir o botão para receber o tratamento\n      charges: Ligaduras no kit\n      max_heals_per_player: "Tratamentos por pessoa no jogo, em todos os kits (0: sem limite)"\n      cooldown_s: "Segundos de espera entre dois tratamentos da mesma pessoa (0: sem espera)"\n      team: "Equipa que o kit serve (vazio: todas)"\n      lang: "Língua do ecrã do kit: pt ou en"\n    commands:\n      refill: Repor as ligaduras\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Medic Kit (Ligaduras): a hit player scans their signed NFC tag\n-- (protocol/nfc-tag.md), then holds a button for params.heal_hold_s seconds\n-- to be healed; letting go early cancels the heal. The kit holds\n-- params.charges heals and shows how many are left. A player gets at most\n-- params.max_heals_per_player heals in the game (0: no limit), and waits\n-- params.cooldown_s between two of them. With params.team the kit serves\n-- that team only. Every refusal says why on the screen.\n--\n-- A role package (modes/README.md): in a field game the kit\'s node runs this\n-- script alone, next to any main mode. The controller\'s field.lua counts the\n-- heals of every kit and tells the kits ("heals" mode command), so a limit\n-- holds across kits; a kit out of its reach goes on with its own count and\n-- what it was told. The GM refills a kit from the console ("refill").\n\nlocal HOLD_STEP_MS = 250 -- shells send team_input.hold this often (modes/README.md)\nlocal SCAN_WINDOW_S = 15 -- after a scan, the hold must start within this time\nlocal SHOW_S = 4 -- a result stays on the screen this long\n\nlocal tag_refusals = {\n  mac = "mac", -- forged: signed with another key\n  game = "game", -- a tag from another game\n  no_game = "no_game", -- this kit is not in a controller\'s game\n  team = "team", -- a team this game does not have\n}\n\n-- Why a tag or a hold was refused, in the kit\'s language (params.lang).\nlocal reasons = {\n  pt = {\n    mac = "Etiqueta falsificada",\n    game = "Etiqueta de outro jogo",\n    no_game = "Este kit não está num jogo",\n    team = "Equipa desconhecida",\n    not_tag = "Não é uma etiqueta do jogo",\n    wrong_team = "Este kit é de outra equipa",\n    limit = "Chegaste ao limite de tratamentos",\n    cooldown = "Espera %d s",\n    cancelled = "Largaste antes do tempo: lê a etiqueta outra vez",\n    scan_first = "Lê primeiro a tua etiqueta",\n  },\n  en = {\n    mac = "Forged tag",\n    game = "Tag from another game",\n    no_game = "This kit is not in a game",\n    team = "Unknown team",\n    not_tag = "Not a game tag",\n    wrong_team = "This kit is for another team",\n    limit = "You have had all your heals",\n    cooldown = "Wait %d s",\n    cancelled = "Let go too early: scan again",\n    scan_first = "Scan your tag first",\n  },\n}\nlocal texts = reasons[params.lang] or reasons.pt\n\nlocal s = state.node { charges = params.charges }\nlocal used = {} -- player -> heals in this game: this kit\'s, and those it was told about\nlocal last = {} -- player -> game time (s) of their last heal\nlocal pending -- after a valid scan: { player, team, base } until the heal or a refusal\nlocal window -- the timer that ends the scan\'s wait for a hold\nlocal back -- the timer that brings the idle screen back\n\nlocal function idle()\n  if back then\n    cancel(back)\n    back = nil\n  end\n  if s.charges <= 0 then\n    ui.screen("medic_empty", { team = params.team })\n  else\n    ui.screen("medic_idle", { remaining = s.charges, team = params.team })\n  end\nend\n\n-- A result screen, then the idle screen again after SHOW_S.\nlocal function show(name, data)\n  if back then\n    cancel(back)\n  end\n  ui.screen(name, data)\n  back = after(SHOW_S, function()\n    back = nil\n    idle()\n  end)\nend\n\nlocal function forget()\n  pending = nil\n  if window then\n    cancel(window)\n    window = nil\n  end\nend\n\nlocal function refuse(reason, data)\n  forget()\n  data = data or {}\n  data.reason = reason\n  data.message = string.format(texts[reason], data.wait_s or 0)\n  data.remaining = s.charges\n  log("medic: refused (" .. reason .. ")" .. (data.player and (" for " .. data.player) or ""))\n  show("medic_refused", data)\nend\n\nlocal function heals_of(player)\n  return used[player] or 0\nend\n\nlocal function heal()\n  local p = pending\n  forget()\n  s.charges = s.charges - 1\n  used[p.player] = heals_of(p.player) + 1\n  last[p.player] = game.time()\n  audio.play("healed")\n  emit("medic.heal", {\n    team = p.team,\n    player = p.player,\n    remaining = s.charges,\n    player_heals_used = used[p.player],\n  })\n  show("medic_healed", {\n    player = p.player,\n    team = p.team,\n    remaining = s.charges,\n    used = used[p.player],\n    max = params.max_heals_per_player,\n  })\n  if s.charges <= 0 then\n    emit("medic.empty", { team = params.team })\n  end\nend\n\nlocal function hold_screen(progress)\n  if back then\n    cancel(back)\n    back = nil\n  end\n  ui.screen("medic_hold", {\n    player = pending.player,\n    team = pending.team,\n    progress = progress,\n    left = math.max(0, math.ceil(params.heal_hold_s * (1 - progress))),\n    remaining = s.charges,\n  })\nend\n\non("game.start", idle)\n\non("nfc.tag", function(e)\n  if not e.valid then\n    log("medic: tag " .. tostring(e.uid) .. " refused: " .. tostring(e.reason))\n    -- unsigned, format and version: not a player tag of this system\n    return refuse(tag_refusals[e.reason] or "not_tag")\n  end\n  local who = { player = e.player, team = e.team }\n  if params.team and e.team ~= params.team then\n    return refuse("wrong_team", who)\n  end\n  if s.charges <= 0 then\n    forget()\n    return idle()\n  end\n  local max = params.max_heals_per_player\n  if max > 0 and heals_of(e.player) >= max then\n    who.used, who.max = heals_of(e.player), max\n    return refuse("limit", who)\n  end\n  local t = last[e.player]\n  if params.cooldown_s > 0 and t and game.time() - t < params.cooldown_s then\n    who.wait_s = math.ceil(params.cooldown_s - (game.time() - t))\n    return refuse("cooldown", who)\n  end\n  forget()\n  pending = { player = e.player, team = e.team }\n  window = after(SCAN_WINDOW_S, function()\n    window = nil\n    pending = nil\n    idle()\n  end)\n  hold_screen(0)\nend)\n\n-- A press after the scan starts the hold from zero; a button already held\n-- when the tag was read counts from its first hold step after the scan.\non("team_input.press", function()\n  if pending then\n    pending.base = 0\n  end\nend)\n\non("team_input.hold", function(e)\n  if not pending then\n    if s.charges > 0 and back == nil then\n      refuse("scan_first")\n    end\n    return\n  end\n  if window then\n    cancel(window)\n    window = nil\n  end\n  if pending.base == nil then\n    pending.base = math.max(0, e.ms - HOLD_STEP_MS)\n  end\n  local progress = (e.ms - pending.base) / (params.heal_hold_s * 1000)\n  if progress >= 1 then\n    heal()\n  else\n    hold_screen(progress)\n  end\nend)\n\non("team_input.release", function()\n  if pending and pending.base ~= nil then\n    refuse("cancelled", { player = pending.player, team = pending.team })\n  end\nend)\n\n-- Mode commands (CMD opcode 8): the controller\'s count of a player\'s heals\n-- at every kit, and the GM\'s refill.\non("cmd.mode", function(e)\n  if e.name == "heals" and type(e.player) == "string" then\n    local n = math.tointeger(e.used) or 0\n    if n > heals_of(e.player) then\n      used[e.player] = n\n    end\n    if type(e.at) == "number" and (last[e.player] == nil or e.at > last[e.player]) then\n      last[e.player] = e.at\n    end\n  elseif e.name == "refill" then\n    s.charges = params.charges\n    log("medic: refilled to " .. s.charges)\n    forget()\n    idle()\n  end\nend)\n',
    'field.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Medic Kit, on the field controller: counts every kit\'s heals per player for\n-- the whole game and tells the kits ("heals" mode command), so a player with a\n-- limit of 2 is not healed twice at every kit. A kit out of reach heals with\n-- its own count; its medic.heal arrives later (the box resends it) and carries\n-- the count the kit knew, so the total here is the larger of the two. A kit\n-- that rebooted is told every count again.\n\nlocal used = {} -- player -> heals in the game, at every kit\nlocal last = {} -- player -> game time (s) the controller heard of their last heal\n\nlocal function tell(node_id, player)\n  field.send(\n    node_id,\n    "mode",\n    { name = "heals", player = player, used = used[player], at = last[player] }\n  )\nend\n\non("medic.heal", function(e)\n  if type(e.player) ~= "string" then\n    return\n  end\n  local n = (used[e.player] or 0) + 1\n  local kit_knew = math.tointeger(e.player_heals_used) or 0\n  if kit_knew > n then\n    n = kit_knew\n  end\n  -- Whole seconds keep the command short (a box takes 127 bytes of parameters).\n  used[e.player], last[e.player] = n, math.floor(game.time())\n  for _, kit in ipairs(field.nodes("medic")) do\n    -- The kit that healed knows its own count unless it was behind.\n    if kit.id ~= e.node or kit_knew < n then\n      tell(kit.id, e.player)\n    end\n  end\nend)\n\non("node.rebooted", function(e)\n  for _, kit in ipairs(field.nodes("medic")) do\n    if kit.id == e.node then\n      for player in pairs(used) do\n        tell(kit.id, player)\n      end\n    end\n  end\nend)\n',
    'assets/screens/medic_empty.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The kit has no heals left until the organisers refill it. Data: team (the\n# team the kit serves, if one). Texts in params.lang (pt or en).\ntemplate: medic_empty\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || \'panel\'}" }\n    children:\n      - type: label\n        text: LIGADURAS\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{params.lang != \'en\'}" }\n      - type: label\n        text: MEDIC KIT\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{params.lang == \'en\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "0"\n    style: { font_size: 48, color: danger }\n  - type: label\n    text: Sem ligaduras\n    style: { font_size: 28, color: danger, visible: "{params.lang != \'en\'}" }\n  - type: label\n    text: The kit is empty\n    style: { font_size: 28, color: danger, visible: "{params.lang == \'en\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: A organização pode repor o kit\n    style:\n      font_size: 14\n      color: muted\n      visible: "{params.lang != \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: The organisers can refill it\n    style:\n      font_size: 14\n      color: muted\n      visible: "{params.lang == \'en\'}"\n      padding: { bottom: 10 }\n',
    'assets/screens/medic_healed.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A heal is done. Data: player, team (the player\'s), remaining (heals left\n# in the kit), used (the player\'s heals in this game), max (heals a player\n# may have; 0: no limit). Texts in params.lang (pt or en).\ntemplate: medic_healed\nstyle: { background: "{team || \'panel\'}" }\nlayout:\n  - type: icon\n    icon: plus\n    style: { font_size: 48, color: contrast }\n  - type: label\n    text: DE VOLTA AO JOGO\n    style: { font_size: 28, color: contrast, visible: "{params.lang != \'en\'}" }\n  - type: label\n    text: BACK IN THE GAME\n    style: { font_size: 28, color: contrast, visible: "{params.lang == \'en\'}" }\n  - type: label\n    text: "{player}"\n    style: { font_size: 20, color: contrast }\n  - type: label\n    text: "Tratamento {used} de {max}"\n    style: { font_size: 20, color: contrast, visible: "{params.lang != \'en\' && max > 0}" }\n  - type: label\n    text: "Heal {used} of {max}"\n    style: { font_size: 20, color: contrast, visible: "{params.lang == \'en\' && max > 0}" }\n  - type: label\n    text: "Restam {remaining} ligaduras"\n    style: { font_size: 14, color: contrast, visible: "{params.lang != \'en\' && remaining != 1}", padding: 6 }\n  - type: label\n    text: Resta 1 ligadura\n    style: { font_size: 14, color: contrast, visible: "{params.lang != \'en\' && remaining == 1}", padding: 6 }\n  - type: label\n    text: "{remaining} heals left in the kit"\n    style: { font_size: 14, color: contrast, visible: "{params.lang == \'en\' && remaining != 1}", padding: 6 }\n  - type: label\n    text: 1 heal left in the kit\n    style: { font_size: 14, color: contrast, visible: "{params.lang == \'en\' && remaining == 1}", padding: 6 }\n',
    'assets/screens/medic_hold.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A player\'s tag was read: the heal fills up while the button is held.\n# Data: player, team (the player\'s), progress (0-1), left (seconds still to\n# hold), remaining (heals left in the kit). Texts in params.lang (pt or en).\ntemplate: medic_hold\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || \'panel\'}" }\n    children:\n      - type: label\n        text: "{player}"\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Mantém premido para tratar\n    style: { font_size: 20, width: 300, align: center, visible: "{params.lang != \'en\'}" }\n  - type: label\n    text: Keep holding to heal\n    style: { font_size: 20, width: 300, align: center, visible: "{params.lang == \'en\'}" }\n  - type: label\n    text: "{left}"\n    style: { font_size: 48, color: accent }\n  - type: progress_bar\n    value: "{progress}"\n    style: { width: 260, height: 14, color: "{team || \'accent\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Largar antes do tempo cancela\n    style:\n      font_size: 14\n      color: muted\n      visible: "{params.lang != \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: Letting go early cancels\n    style:\n      font_size: 14\n      color: muted\n      visible: "{params.lang == \'en\'}"\n      padding: { bottom: 10 }\n',
    'assets/screens/medic_idle.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The kit waits for a player\'s tag. Data: remaining (heals left), team (the\n# team the kit serves, if one). The texts follow the game\'s params.lang\n# (pt, the default, or en).\ntemplate: medic_idle\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || \'panel\'}" }\n    children:\n      - type: label\n        text: LIGADURAS\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{params.lang != \'en\'}" }\n      - type: label\n        text: MEDIC KIT\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{params.lang == \'en\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{remaining}"\n    style: { font_size: 48, color: "{remaining <= 1 && \'orange\' || \'white\'}" }\n  - type: label\n    text: "Restam {remaining} ligaduras"\n    style: { font_size: 20, color: muted, visible: "{params.lang != \'en\' && remaining != 1}" }\n  - type: label\n    text: Resta 1 ligadura\n    style: { font_size: 20, color: muted, visible: "{params.lang != \'en\' && remaining == 1}" }\n  - type: label\n    text: "{remaining} heals left"\n    style: { font_size: 20, color: muted, visible: "{params.lang == \'en\' && remaining != 1}" }\n  - type: label\n    text: 1 heal left\n    style: { font_size: 20, color: muted, visible: "{params.lang == \'en\' && remaining == 1}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Lê a tua etiqueta\n    style: { font_size: 28, color: accent, visible: "{params.lang != \'en\'}" }\n  - type: label\n    text: Scan your tag\n    style: { font_size: 28, color: accent, visible: "{params.lang == \'en\'}" }\n  - type: label\n    text: e mantém premido o botão\n    style:\n      font_size: 14\n      color: muted\n      visible: "{params.lang != \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: then hold the button\n    style:\n      font_size: 14\n      color: muted\n      visible: "{params.lang == \'en\'}"\n      padding: { bottom: 10 }\n',
    'assets/screens/medic_refused.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A tag or a hold was refused. Data: reason (mac, game, no_game, team,\n# not_tag, wrong_team, limit, cooldown, cancelled, scan_first), message (the\n# reason in params.lang, from the script), player and team (when the tag was\n# a player\'s), remaining (heals left in the kit).\ntemplate: medic_refused\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: danger }\n    children:\n      - type: label\n        text: RECUSADO\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{params.lang != \'en\'}" }\n      - type: label\n        text: REFUSED\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{params.lang == \'en\'}" }\n  - type: spacer\n    height: fill\n  - type: icon\n    icon: close\n    style: { font_size: 48, color: danger }\n  - type: label\n    text: "{message}"\n    style: { font_size: 20, width: 300, align: center }\n  - type: label\n    text: "{player}"\n    style: { font_size: 20, color: "{team || \'muted\'}", visible: "{player}" }\n  - type: spacer\n    height: fill\n',
  },
  'objectives': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.objectives\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\n# A role package for custom scenarios (decision P4R7): a scenario package (kind: scenario, a\n# field.lua only) leads the game (org.club.foxhound+org.atalaia.objectives) and tells each node\n# what it is for with the mode command "setup". The box side never changes per scenario.\nkind: role\nname: Objectives\ndescription: >-\n  The boxes and props of a custom scenario. Each one waits for the scenario, on the field\n  controller, to tell it what it is for: a point to capture by holding a team button, a code to\n  type on the keypad, player tags to scan, or a bomb site to arm and defuse. It reports what\n  happens and never scores: the scenario decides when an objective is completed or failed, and\n  tells the node again after a reboot.\nroles:\n  objective: { requires: [team_input], optional: [keypad, nfc, display, audio, team_display] }\n  bomb_site: { requires: [team_input], optional: [display, audio] }\ni18n:\n  pt:\n    name: Objetivos\n    description: >-\n      As caixas e os adereços de um cenário personalizado. Cada um espera que o cenário, no\n      controlador de campo, lhe diga para que serve: um ponto a capturar mantendo premido o botão\n      de uma equipa, um código a marcar no teclado, etiquetas de jogador a ler, ou um local de\n      bomba a armar e a desarmar. Informa o que acontece e nunca pontua: o cenário decide quando um\n      objetivo é cumprido ou falhado, e volta a configurar o nó depois de um reinício.\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Objectives (org.atalaia.objectives), the nodes of a custom scenario\n-- (decision P4R7). A node does nothing of its own: it waits for the mode\n-- command "setup" from the scenario\'s field.lua on the controller, which says\n-- what the node is for, and reports what happens with the standard events. It\n-- never scores: the scenario decides when an objective is completed or failed.\n--\n-- setup (every field optional but kind; at most 127 bytes of JSON):\n--   kind      capture, code, tags, bomb; off (inactive, a hidden objective);\n--             done (completed: team, the team that completed it, if one);\n--             failed\n--   team      capture, code, tags: the only team that may do it (code: the\n--             team credited); bomb: the attackers, who arm (any other team\n--             defuses). Empty: every team.\n--   label     the objective\'s short name, in the scenario\'s language\n--   lang      pt (the default) or en: the screen\'s texts\n--   hold_ms   capture and arm: how long a team holds its input (3000)\n--   defuse_ms bomb: how long a team holds to defuse (hold_ms)\n--   code      code: the digits to type, then #\n--   count     tags: how many tags a team scans (1): players\' own tags, or with\n--             any, any cards (intel), for team or the last team to press\n--   any       tags: true for any card, not only players\' tags\n--   fuse_s    bomb: the fuse (60)\n--   holder    capture: the team holding the node (after a reboot)\n--   have      tags: the tags of team already counted (after a reboot)\n--   armed     bomb: the team that armed it (after a reboot), with left, the\n--             seconds left on the fuse; the bomb goes on without a new event\n--\n-- Reports: zone.captured / zone.neutralized (capture, and the GM\'s owner\n-- override), code.used (code: no code in the event, only the team), tag.scanned\n-- (tags: tag, the card\'s uid; owner, the player; team), bomb.armed / bomb.defused /\n-- bomb.exploded (bomb). A script does not know its role (decision M5-5): the\n-- setup\'s kind is what the node does, so one script serves both roles.\n\nlocal cfg = {} -- the last setup\nlocal holder -- capture: the team holding the node\nlocal typed, note = "", nil -- code: the digits typed; the bottom line (wrong, ok, ...)\nlocal got, seen = {}, {} -- tags: team -> tags counted; uid -> true\nlocal phase, by, explode_at, fuse -- bomb: standby, armed, defused, exploded\nlocal last_team -- the last team to press its input (code: the team credited)\n\nlocal function int(v, lo, hi, default)\n  v = math.tointeger(v)\n  if v == nil or v < lo or v > hi then\n    return default\n  end\n  return v\nend\n\nlocal function show()\n  local k = cfg.kind\n  local d = { lang = cfg.lang, label = cfg.label }\n  if k == "capture" then\n    d.team, d.only, d.hold_ms = holder, cfg.team, cfg.hold_ms\n    ui.screen("obj_capture", d)\n  elseif k == "code" then\n    d.team, d.digits, d.note = cfg.team or last_team, #typed, note\n    ui.screen("obj_code", d)\n  elseif k == "tags" then\n    local team = cfg.team or cfg.last\n    d.team, d.have, d.count, d.note, d.any = team, team and got[team] or 0, cfg.count, note, cfg.any\n    ui.screen("obj_tags", d)\n  elseif k == "bomb" then\n    d.phase, d.team, d.attackers, d.fuse_s = phase, by, cfg.team, cfg.fuse_s\n    d.left = phase == "armed" and math.max(0, math.ceil(explode_at - game.time())) or 0\n    ui.screen("obj_bomb", d)\n  else\n    d.state, d.team = k or "wait", k == "done" and cfg.team or nil -- wait, off, done, failed\n    ui.screen("obj_status", d)\n  end\nend\n\nlocal function may(team)\n  return cfg.team == nil or team == cfg.team\nend\n\n-- Capture.\n\nlocal function take(team, squad)\n  emit("zone.captured", { team = team, squad = squad, previous_team = holder })\n  holder = team\n  cap("team_display"):show(team)\n  audio.play("captured")\n  show()\nend\n\n-- Bomb site.\n\nlocal function arm(team, left, quiet)\n  phase, by, explode_at = "armed", team, game.time() + left\n  fuse = after(left, function()\n    fuse, phase = nil, "exploded"\n    audio.play("explosion")\n    emit("bomb.exploded", { team = by })\n    show()\n  end)\n  if not quiet then\n    audio.play("armed")\n    emit("bomb.armed", { team = team, fuse_s = left })\n  end\n  show()\nend\n\nlocal function defuse(team)\n  cancel(fuse)\n  fuse, phase, by = nil, "defused", team\n  audio.play("defused")\n  emit("bomb.defused", { team = team })\n  show()\nend\n\non("game.start", show)\n\non("cmd.mode", function(e)\n  if e.name ~= "setup" then\n    return\n  end\n  if fuse then\n    cancel(fuse)\n  end\n  local hold = int(e.hold_ms, 0, 600000, 3000)\n  cfg = {\n    kind = e.kind,\n    team = e.team ~= "" and e.team or nil,\n    label = e.label,\n    lang = e.lang,\n    hold_ms = hold,\n    defuse_ms = int(e.defuse_ms, 0, 600000, hold),\n    code = type(e.code) == "string" and e.code or nil,\n    count = int(e.count, 1, 100, 1),\n    any = e.any == true,\n    fuse_s = int(e.fuse_s, 10, 3600, 60),\n  }\n  holder, typed, note, got, seen = e.holder ~= "" and e.holder or nil, "", nil, {}, {}\n  phase, by, fuse = "standby", nil, nil\n  if cfg.kind == "tags" and cfg.team then\n    got[cfg.team] = int(e.have, 0, 100, 0)\n  end\n  if holder then\n    cap("team_display"):show(holder)\n  end\n  if cfg.kind == "bomb" and type(e.armed) == "string" then\n    return arm(e.armed, int(e.left, 1, 3600, cfg.fuse_s), true)\n  end\n  show()\nend)\n\non("team_input.press", function(e)\n  last_team = e.team\nend)\n\non("team_input.hold", function(e)\n  local k = cfg.kind\n  if k == "capture" then\n    if e.team ~= holder and e.ms >= cfg.hold_ms and may(e.team) then\n      take(e.team, e.squad)\n    end\n  elseif k == "bomb" then\n    if phase == "standby" and e.ms >= cfg.hold_ms and may(e.team) then\n      arm(e.team, cfg.fuse_s)\n    elseif phase == "armed" and e.team ~= by and e.ms >= cfg.defuse_ms then\n      defuse(e.team)\n    end\n  end\nend)\n\n-- The GM\'s owner override (the console\'s Boxes tab), for a capture only.\non("cmd.set_owner", function(e)\n  if cfg.kind ~= "capture" then\n    return\n  end\n  local team = e.team\n  if team == "" or team == "none" then\n    team = nil\n  end\n  if team == holder then\n    return\n  end\n  if team then\n    return take(team)\n  end\n  emit("zone.neutralized", { previous_team = holder })\n  holder = nil\n  cap("team_display"):show("none")\n  show()\nend)\n\n-- Code: digits, then #; * clears. A wrong code is only on the screen.\non("keypad.key", function(e)\n  if cfg.kind ~= "code" or note == "ok" then\n    return\n  end\n  local k = e.key\n  if k == "#" then\n    if cfg.code and typed == cfg.code then\n      note = "ok"\n      emit("code.used", { team = cfg.team or last_team })\n      audio.play("captured")\n    else\n      note = "wrong"\n    end\n    typed = ""\n  elseif k == "*" then\n    typed, note = "", nil\n  elseif string.match(k or "", "^%d\$") and #typed < 8 then\n    typed, note = typed .. k, nil\n  end\n  show()\nend)\n\n-- Tags: each player of a team scans their own tag once; with any, any card\n-- (intel cards) counts once, for the team at the box.\non("nfc.tag", function(e)\n  if cfg.kind ~= "tags" then\n    return\n  end\n  local team = e.team\n  if cfg.any then\n    team = cfg.team or last_team\n  end\n  if not cfg.any and not e.valid then\n    note = "not_tag"\n  elseif team == nil then\n    note = "team_first"\n  elseif not may(team) then\n    note = "wrong_team"\n  else\n    cfg.last = team\n    local n = got[team] or 0\n    if seen[e.uid] or n >= cfg.count then\n      note = "again"\n    else\n      seen[e.uid], got[team], note = true, n + 1, nil\n      emit("tag.scanned", { team = team, tag = e.uid, owner = e.valid and e.player or nil })\n    end\n  end\n  show()\nend)\n\nevery(1, function()\n  if cfg.kind == "bomb" and phase == "armed" then\n    show()\n  end\nend)\n\non("game.end", function()\n  ui.screen("final_score", { owner = holder })\nend)\n',
    'assets/screens/obj_bomb.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A bomb site. Data: phase (standby, armed, defused, exploded), team (armed,\n# exploded: the team that armed it; defused: the team that defused it),\n# attackers (the only team that may arm it, if one), left (armed: seconds\n# left), fuse_s, label (the objective\'s name), lang (pt, the default, or en).\ntemplate: obj_bomb\nstyle: { background: "{phase == \'exploded\' && \'danger\' || \'background\'}" }\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{phase == \'armed\' && \'danger\' || \'panel\'}" }\n    children:\n      - type: label\n        text: "{label || \'LOCAL DA BOMBA\'}"\n        style: { font_size: 20, width: fill, align: center, visible: "{lang != \'en\'}" }\n      - type: label\n        text: "{label || \'BOMB SITE\'}"\n        style: { font_size: 20, width: fill, align: center, visible: "{lang == \'en\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{left|clock}"\n    style: { font_size: 48, color: "{left <= 10 && \'danger\' || \'white\'}", visible: "{phase == \'armed\'}" }\n  - type: progress_bar\n    value: "{left / fuse_s}"\n    style: { width: 240, height: 10, color: "{team || \'danger\'}", visible: "{phase == \'armed\'}" }\n  - type: label\n    text: Mantém premido para desarmar\n    style:\n      font_size: 14\n      color: muted\n      visible: "{phase == \'armed\' && lang != \'en\'}"\n      padding: { top: 6 }\n  - type: label\n    text: Hold to defuse\n    style:\n      font_size: 14\n      color: muted\n      visible: "{phase == \'armed\' && lang == \'en\'}"\n      padding: { top: 6 }\n  - type: label\n    text: Mantém premido para armar\n    style: { font_size: 20, color: accent, visible: "{phase == \'standby\' && lang != \'en\'}" }\n  - type: label\n    text: Hold to arm\n    style: { font_size: 28, color: accent, visible: "{phase == \'standby\' && lang == \'en\'}" }\n  - type: label\n    text: DESARMADA\n    style: { font_size: 28, color: "{team || \'accent\'}", visible: "{phase == \'defused\' && lang != \'en\'}" }\n  - type: label\n    text: DEFUSED\n    style: { font_size: 28, color: "{team || \'accent\'}", visible: "{phase == \'defused\' && lang == \'en\'}" }\n  - type: label\n    text: EXPLODIU\n    style: { font_size: 28, color: white, visible: "{phase == \'exploded\' && lang != \'en\'}" }\n  - type: label\n    text: EXPLODED\n    style: { font_size: 28, color: white, visible: "{phase == \'exploded\' && lang == \'en\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "Armada por {team|upper}"\n    style:\n      font_size: 14\n      color: team\n      visible: "{phase == \'armed\' && lang != \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: "Armed by {team|upper}"\n    style:\n      font_size: 14\n      color: team\n      visible: "{phase == \'armed\' && lang == \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: "Só a equipa {attackers} arma"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{phase == \'standby\' && attackers && lang != \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: "Only {attackers} arms it"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{phase == \'standby\' && attackers && lang == \'en\'}"\n      padding: { bottom: 10 }\n',
    'assets/screens/obj_capture.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A point to capture. Data: team (the team holding it, if one), only (the only\n# team that may capture it, if one), hold_ms (how long to hold), label (the\n# objective\'s name), lang (pt, the default, or en).\ntemplate: obj_capture\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || \'panel\'}" }\n    children:\n      - type: label\n        text: "{label || \'CAPTURAR\'}"\n        style: { font_size: 20, width: fill, align: center, color: "{team && \'contrast\' || \'white\'}", visible: "{lang != \'en\'}" }\n      - type: label\n        text: "{label || \'CAPTURE\'}"\n        style: { font_size: 20, width: fill, align: center, color: "{team && \'contrast\' || \'white\'}", visible: "{lang == \'en\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{team|upper}"\n    style: { font_size: 48, color: team, visible: "{team}" }\n  - type: label\n    text: tem este ponto\n    style: { font_size: 20, color: muted, visible: "{team && lang != \'en\'}" }\n  - type: label\n    text: holds this point\n    style: { font_size: 20, color: muted, visible: "{team && lang == \'en\'}" }\n  - type: label\n    text: MANTÉM PREMIDO\n    style: { font_size: 28, color: accent, visible: "{!team && lang != \'en\'}" }\n  - type: label\n    text: HOLD TO CAPTURE\n    style: { font_size: 28, color: accent, visible: "{!team && lang == \'en\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "Mantém premido {hold_ms / 1000} s para capturar"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{!only && lang != \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: "Hold your button {hold_ms / 1000} s to capture"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{!only && lang == \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: "Só a equipa {only} captura: {hold_ms / 1000} s"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{only && lang != \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: "Only {only} captures: {hold_ms / 1000} s"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{only && lang == \'en\'}"\n      padding: { bottom: 10 }\n',
    'assets/screens/obj_code.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A code to type on the keypad. Data: team (the team credited, if known),\n# digits (how many digits are typed: the code itself is never shown), note\n# (wrong: the last code was wrong; ok: the right code was typed), label (the\n# objective\'s name), lang (pt, the default, or en).\ntemplate: obj_code\nstyle: { background: "{note == \'ok\' && team || \'background\'}" }\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || \'panel\'}" }\n    children:\n      - type: label\n        text: "{label || \'CÓDIGO\'}"\n        style: { font_size: 20, width: fill, align: center, color: "{team && \'contrast\' || \'white\'}", visible: "{lang != \'en\'}" }\n      - type: label\n        text: "{label || \'CODE\'}"\n        style: { font_size: 20, width: fill, align: center, color: "{team && \'contrast\' || \'white\'}", visible: "{lang == \'en\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{digits}"\n    style: { font_size: 48, color: accent, visible: "{note != \'ok\'}" }\n  - type: label\n    text: algarismos marcados\n    style: { font_size: 20, color: muted, visible: "{note != \'ok\' && lang != \'en\'}" }\n  - type: label\n    text: digits typed\n    style: { font_size: 20, color: muted, visible: "{note != \'ok\' && lang == \'en\'}" }\n  - type: icon\n    icon: ok\n    style: { font_size: 48, color: "{team && \'contrast\' || \'accent\'}", visible: "{note == \'ok\'}" }\n  - type: label\n    text: CÓDIGO ACEITE\n    style: { font_size: 28, color: "{team && \'contrast\' || \'white\'}", visible: "{note == \'ok\' && lang != \'en\'}" }\n  - type: label\n    text: CODE ACCEPTED\n    style: { font_size: 28, color: "{team && \'contrast\' || \'white\'}", visible: "{note == \'ok\' && lang == \'en\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Código errado\n    style:\n      font_size: 20\n      color: danger\n      visible: "{note == \'wrong\' && lang != \'en\'}"\n      padding: { bottom: 8 }\n  - type: label\n    text: Wrong code\n    style:\n      font_size: 20\n      color: danger\n      visible: "{note == \'wrong\' && lang == \'en\'}"\n      padding: { bottom: 8 }\n  - type: label\n    text: "Marca o código e #  (* apaga)"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{!note && lang != \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: "Type the code, then #  (* clears)"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{!note && lang == \'en\'}"\n      padding: { bottom: 10 }\n',
    'assets/screens/obj_status.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A node with nothing to do. Data: state (wait: no setup from the scenario yet;\n# off: a hidden or inactive objective; done: completed; failed), team (done: the team\n# that completed it, if one), label (the objective\'s name, from the setup),\n# lang (pt, the default, or en).\ntemplate: obj_status\nstyle: { background: "{state == \'done\' && team || \'background\'}" }\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: panel }\n    children:\n      - type: label\n        text: "{label || \'OBJETIVO\'}"\n        style: { font_size: 20, width: fill, align: center, visible: "{lang != \'en\'}" }\n      - type: label\n        text: "{label || \'OBJECTIVE\'}"\n        style: { font_size: 20, width: fill, align: center, visible: "{lang == \'en\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: À espera do cenário\n    style: { font_size: 28, visible: "{state == \'wait\' && lang != \'en\'}" }\n  - type: label\n    text: Waiting for the scenario\n    style: { font_size: 28, visible: "{state == \'wait\' && lang == \'en\'}" }\n  - type: label\n    text: Objetivo inativo\n    style: { font_size: 28, color: muted, visible: "{state == \'off\' && lang != \'en\'}" }\n  - type: label\n    text: Objective inactive\n    style: { font_size: 28, color: muted, visible: "{state == \'off\' && lang == \'en\'}" }\n  - type: icon\n    icon: ok\n    style: { font_size: 48, color: "{team && \'contrast\' || \'accent\'}", visible: "{state == \'done\'}" }\n  - type: label\n    text: CUMPRIDO\n    style: { font_size: 28, color: "{team && \'contrast\' || \'white\'}", visible: "{state == \'done\' && lang != \'en\'}" }\n  - type: label\n    text: COMPLETE\n    style: { font_size: 28, color: "{team && \'contrast\' || \'white\'}", visible: "{state == \'done\' && lang == \'en\'}" }\n  - type: label\n    text: FALHADO\n    style: { font_size: 28, color: danger, visible: "{state == \'failed\' && lang != \'en\'}" }\n  - type: label\n    text: FAILED\n    style: { font_size: 28, color: danger, visible: "{state == \'failed\' && lang == \'en\'}" }\n  - type: label\n    text: "{team|upper}"\n    style: { font_size: 20, color: contrast, visible: "{state == \'done\' && team}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Configurado pelo controlador de campo\n    style:\n      font_size: 14\n      color: muted\n      visible: "{state == \'wait\' && lang != \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: Set up by the field controller\n    style:\n      font_size: 14\n      color: muted\n      visible: "{state == \'wait\' && lang == \'en\'}"\n      padding: { bottom: 10 }\n',
    'assets/screens/obj_tags.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# Player tags to scan. Data: team (the team of the last tag counted, or the\n# only team that may scan), have (that team\'s tags counted), count (how many it\n# needs), note (not_tag: not a player tag of this game; team_first: a card, and\n# no team has pressed its button yet; wrong_team: a team that may not scan\n# here; again: a tag already counted, or the team already has them all), any\n# (any card counts, not only players\' tags), label (the objective\'s name),\n# lang (pt, the default, or en).\ntemplate: obj_tags\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || \'panel\'}" }\n    children:\n      - type: label\n        text: "{label || \'ETIQUETAS\'}"\n        style: { font_size: 20, width: fill, align: center, color: "{team && \'contrast\' || \'white\'}", visible: "{lang != \'en\'}" }\n      - type: label\n        text: "{label || \'TAGS\'}"\n        style: { font_size: 20, width: fill, align: center, color: "{team && \'contrast\' || \'white\'}", visible: "{lang == \'en\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{have} / {count}"\n    style: { font_size: 48, color: "{team || \'accent\'}" }\n  - type: progress_bar\n    value: "{have / count}"\n    style: { width: 260, height: 14, color: "{team || \'accent\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Não é uma etiqueta do jogo\n    style:\n      font_size: 20\n      color: danger\n      visible: "{note == \'not_tag\' && lang != \'en\'}"\n      padding: { bottom: 8 }\n  - type: label\n    text: Not a game tag\n    style:\n      font_size: 20\n      color: danger\n      visible: "{note == \'not_tag\' && lang == \'en\'}"\n      padding: { bottom: 8 }\n  - type: label\n    text: Objetivo de outra equipa\n    style:\n      font_size: 20\n      color: danger\n      visible: "{note == \'wrong_team\' && lang != \'en\'}"\n      padding: { bottom: 8 }\n  - type: label\n    text: Another team\'s objective\n    style:\n      font_size: 20\n      color: danger\n      visible: "{note == \'wrong_team\' && lang == \'en\'}"\n      padding: { bottom: 8 }\n  - type: label\n    text: Carrega no botão da equipa\n    style:\n      font_size: 20\n      color: danger\n      visible: "{note == \'team_first\' && lang != \'en\'}"\n      padding: { bottom: 8 }\n  - type: label\n    text: Press your team\'s button\n    style:\n      font_size: 20\n      color: danger\n      visible: "{note == \'team_first\' && lang == \'en\'}"\n      padding: { bottom: 8 }\n  - type: label\n    text: Esta etiqueta já conta\n    style:\n      font_size: 20\n      color: muted\n      visible: "{note == \'again\' && lang != \'en\'}"\n      padding: { bottom: 8 }\n  - type: label\n    text: This tag already counts\n    style:\n      font_size: 20\n      color: muted\n      visible: "{note == \'again\' && lang == \'en\'}"\n      padding: { bottom: 8 }\n  - type: label\n    text: Cada pessoa lê a sua etiqueta\n    style:\n      font_size: 14\n      color: muted\n      visible: "{!note && !any && lang != \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: Each player scans their own tag\n    style:\n      font_size: 14\n      color: muted\n      visible: "{!note && !any && lang == \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: Lê os cartões que encontraste\n    style:\n      font_size: 14\n      color: muted\n      visible: "{!note && any && lang != \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: Scan the cards you found\n    style:\n      font_size: 14\n      color: muted\n      visible: "{!note && any && lang == \'en\'}"\n      padding: { bottom: 10 }\n',
  },
  'player_checkin': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.player_checkin\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nkind: mode\nname: Player Check-in\ndescription: >-\n  Players check in at a checkpoint by scanning their signed NFC tag. The box counts the players of each\n  team and gives their team points for each check-in. A player counts once, or again after a set time.\n  Forged tags and tags from another game are refused.\nroles:\n  checkpoint: { requires: [nfc], optional: [display] }\nparams:\n  points:         { type: int, min: 0, max: 1000, default: 1, label: "Points for the player\'s team per check-in" }\n  repeat_after_s: { type: int, min: 0, max: 86400, default: 0, label: "Seconds before the same player counts again (0: once per game)" }\ni18n:\n  pt:\n    name: Registo de Presença\n    description: >-\n      Cada participante faz o registo num ponto de controlo lendo a sua etiqueta NFC assinada. A caixa conta\n      as pessoas de cada equipa e dá pontos à equipa por cada registo. Cada pessoa conta uma vez, ou de\n      novo ao fim de um tempo definido. Etiquetas falsificadas ou de outro jogo são recusadas.\n    params:\n      points: Pontos para a equipa por cada registo\n      repeat_after_s: "Segundos até a mesma pessoa voltar a contar (0: uma vez por jogo)"\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Player Check-in: players check in at a checkpoint with their signed NFC\n-- tag (protocol/nfc-tag.md). The box counts check-ins per team and gives the\n-- player\'s team `points` for each. A player counts once per game, or again\n-- after repeat_after_s seconds; a scan before that is a duplicate and is\n-- refused. Forged tags, tags from another game and tags without a team are\n-- refused (the shell checks the signature and says why in nfc.tag\'s reason).\n\nlocal refused = {\n  unsigned = "Not a game tag",\n  no_game = "No game: join one first",\n  game = "Tag from another game",\n  mac = "Forged tag",\n  team = "Unknown team",\n  format = "Damaged tag",\n  version = "Unknown tag version",\n}\n\nlocal seen = {} -- player -> game time of their last check-in that counted\nlocal count = {} -- team -> check-ins\nlocal order = {} -- teams in the order they first checked in\nlocal total = 0\nlocal last_team\nlocal message, failed, fade\n\nlocal function counts()\n  local parts = {}\n  for _, team in ipairs(order) do\n    parts[#parts + 1] = string.upper(team) .. " " .. count[team]\n  end\n  return table.concat(parts, "  ")\nend\n\nlocal function show()\n  ui.screen("checkin", {\n    total = total,\n    counts = counts(),\n    team = last_team,\n    message = message,\n    error = failed,\n  })\nend\n\n-- A message under the counts, cleared after 4 s.\nlocal function say(text, bad)\n  message, failed = text, bad\n  show()\n  if fade then\n    cancel(fade)\n  end\n  fade = after(4, function()\n    fade = nil\n    message, failed = nil, false\n    show()\n  end)\nend\n\non("game.start", show)\n\non("nfc.tag", function(e)\n  if not e.valid then\n    log("check-in: tag " .. tostring(e.uid) .. " refused: " .. tostring(e.reason))\n    return say(refused[e.reason] or "Not a game tag", true)\n  end\n  if e.team == nil then\n    return say("This tag has no team", true)\n  end\n  local t = seen[e.player]\n  if t and (params.repeat_after_s == 0 or game.time() - t < params.repeat_after_s) then\n    return say("Already checked in", true)\n  end\n  seen[e.player] = game.time()\n  if count[e.team] == nil then\n    count[e.team] = 0\n    order[#order + 1] = e.team\n  end\n  count[e.team] = count[e.team] + 1\n  total = total + 1\n  last_team = e.team\n  emit("player.checkin", { team = e.team, player = e.player })\n  score.add(e.team, params.points, "checkin")\n  say("Checked in: " .. e.player, false)\nend)\n',
    'assets/screens/checkin.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The checkpoint. Data: total (check-ins), counts (per team, as text),\n# team (of the last check-in), message, error.\ntemplate: checkin\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || \'panel\'}" }\n    children:\n      - type: label\n        text: CHECK-IN\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{total}"\n    style: { font_size: 48 }\n  - type: label\n    text: players checked in\n    style: { font_size: 20, color: muted }\n  - type: label\n    text: "{counts}"\n    style: { font_size: 20, visible: "{counts}" }\n  - type: label\n    text: "{message}"\n    style:\n      font_size: 20\n      width: 300\n      color: "{error && \'danger\' || \'accent\'}"\n      visible: "{message}"\n      padding: { top: 6 }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Scan your tag to check in\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
  },
  'respawn': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.respawn\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nkind: mode\nname: Respawn and Lives\ndescription: >-\n  A respawn point counts lives. Players scan their signed NFC tag (or press their team\'s button) to come\n  back into the game; each respawn takes a life from their team, or from the player with per-player\n  lives, and a player must wait a cooldown between respawns. When a team has no lives left, the next\n  respawn is refused and the team is eliminated.\nroles:\n  respawn: { requires: [nfc], optional: [team_input, display] }\nparams:\n  lives:              { type: int, min: 1, max: 1000, default: 20, label: "Lives: respawns per team, or per player with per-player lives" }\n  per_player:         { type: bool, default: false, label: "Count lives per player (needs NFC tags) instead of per team" }\n  respawn_cooldown_s: { type: int, min: 0, max: 600, default: 30, label: "Seconds a player waits between respawns" }\ni18n:\n  pt:\n    name: Reentradas e Vidas\n    description: >-\n      Um ponto de reentrada conta as vidas. Cada participante lê a sua etiqueta NFC assinada (ou carrega no\n      botão da sua equipa) para voltar ao jogo; cada reentrada gasta uma vida da equipa, ou da própria\n      pessoa com vidas individuais, e há um tempo de espera entre reentradas. Quando uma equipa fica sem\n      vidas, a reentrada seguinte é recusada e a equipa é eliminada.\n    params:\n      lives: "Vidas: reentradas por equipa, ou por pessoa com vidas individuais"\n      per_player: Contar as vidas por pessoa (precisa de etiquetas NFC) em vez de por equipa\n      respawn_cooldown_s: Segundos de espera entre reentradas de cada pessoa\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Respawn and Lives: a respawn point counts lives. A player scans their\n-- signed NFC tag (protocol/nfc-tag.md), or presses their team\'s button, to\n-- come back into the game. Each respawn takes one of the team\'s `lives`, or\n-- one of the player\'s own with per_player. A player waits respawn_cooldown_s\n-- between respawns; button presses carry no player, so they only have a 2 s\n-- guard against double presses. When a team has no lives left, the next\n-- respawn is refused and team.eliminated is sent (once). Lives are counted on\n-- this box: give each team one respawn point, or share one.\n\nlocal refused = {\n  unsigned = "Not a game tag",\n  no_game = "No game: join one first",\n  game = "Tag from another game",\n  mac = "Forged tag",\n  team = "Unknown team",\n  format = "Damaged tag",\n  version = "Unknown tag version",\n}\nlocal BUTTON_GUARD_S = 2\n\nlocal lives = {} -- team, or player with per_player -> lives left\nlocal last = {} -- player id, or "team:<team>" for buttons -> game time of the last respawn\nlocal out = {} -- team -> true once team.eliminated was sent\nlocal message, failed, fade\nlocal shown = { lives = params.lives }\n\nlocal function show()\n  ui.screen("respawn", {\n    team = shown.team,\n    player = shown.player,\n    lives = shown.lives,\n    message = message,\n    error = failed,\n  })\nend\n\n-- A message under the lives count, cleared after 4 s.\nlocal function say(text, bad)\n  message, failed = text, bad\n  show()\n  if fade then\n    cancel(fade)\n  end\n  fade = after(4, function()\n    fade = nil\n    message, failed = nil, false\n    show()\n  end)\nend\n\nlocal function lives_of(key)\n  if lives[key] == nil then\n    lives[key] = params.lives\n  end\n  return lives[key]\nend\n\nlocal function respawn(team, player)\n  if params.per_player and player == nil then\n    return say("Scan your tag", true)\n  end\n  if team == nil and not params.per_player then\n    return say("This tag has no team", true)\n  end\n  local who = player or ("team:" .. team)\n  local wait_s = player and params.respawn_cooldown_s or BUTTON_GUARD_S\n  local t = last[who]\n  if t and game.time() - t < wait_s then\n    return say("Wait " .. math.ceil(wait_s - (game.time() - t)) .. " s", true)\n  end\n  local key = params.per_player and player or team\n  shown.team, shown.player = team, player\n  shown.lives = lives_of(key)\n  if lives_of(key) <= 0 then\n    if not params.per_player and not out[team] then\n      out[team] = true\n      emit("team.eliminated", { team = team })\n    end\n    return say(params.per_player and "No lives left" or "No lives left: team out", true)\n  end\n  lives[key] = lives[key] - 1\n  last[who] = game.time()\n  shown.lives = lives[key]\n  emit("player.respawn", { team = team, player = player, lives_left = lives[key] })\n  say("Back in the game", false)\nend\n\non("game.start", show)\n\non("nfc.tag", function(e)\n  if not e.valid then\n    log("respawn: tag " .. tostring(e.uid) .. " refused: " .. tostring(e.reason))\n    return say(refused[e.reason] or "Not a game tag", true)\n  end\n  respawn(e.team, e.player)\nend)\n\non("team_input.press", function(e)\n  respawn(e.team, nil)\nend)\n',
    'assets/screens/respawn.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The respawn point. Data: lives (left, for the last team or player),\n# team, player (the last respawn), message, error.\ntemplate: respawn\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || \'panel\'}" }\n    children:\n      - type: label\n        text: RESPAWN\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lives}"\n    style: { font_size: 48, color: "{lives == 0 && \'danger\' || \'white\'}" }\n  - type: label\n    text: lives left\n    style: { font_size: 20, color: muted, visible: "{!team && !player}" }\n  - type: label\n    text: "lives left for {team|upper}"\n    style: { font_size: 20, color: team, visible: "{team && !params.per_player}" }\n  - type: label\n    text: "lives left for {player}"\n    style: { font_size: 20, color: muted, visible: "{player && params.per_player}" }\n  - type: label\n    text: "{message}"\n    style:\n      font_size: 20\n      width: 300\n      color: "{error && \'danger\' || \'accent\'}"\n      visible: "{message}"\n      padding: { top: 6 }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Scan your tag to come back in\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
  },
  'target_windows': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.target_windows\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nname: Target Windows\ndescription: >-\n  A target lights up in a random team\'s colour for a few seconds; a hit while it is lit scores for that\n  team. Needs the target addon (a hit sensor and an LED ring).\nroles:\n  target: { requires: [hit, led], optional: [display, audio] }\nparams:\n  interval_s:   { type: int, min: 1, max: 3600, default: 20, label: "Seconds the target stays dark between windows" }\n  window_s:     { type: int, min: 1, max: 600,  default: 5,  label: "Seconds a window stays open" }\n  hit_points:   { type: int, min: 1, max: 1000, default: 5,  label: "Points for a hit in the window" }\n  min_strength: { type: int, min: 0, max: 255,  default: 40, label: "Weakest hit that counts (0-255)" }\n  multi_hit:    { type: bool, default: false, label: "Every hit in a window scores (otherwise the first hit closes it)" }\ni18n:\n  pt:\n    name: Janelas de Alvo\n    description: >-\n      Um alvo acende-se na cor de uma equipa ao acaso durante alguns segundos; um tiro enquanto está aceso\n      pontua para essa equipa. Precisa do módulo de alvo (um sensor de impacto e um anel de LED).\n    params:\n      interval_s: Segundos em que o alvo fica apagado entre janelas\n      window_s: Segundos que uma janela fica aberta\n      hit_points: Pontos por um tiro na janela\n      min_strength: Impacto mais fraco que conta (0-255)\n      multi_hit: Todos os tiros numa janela pontuam (senão, o primeiro fecha-a)\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Target Windows, on each target (decision P4R4): the target stays dark for\n-- params.interval_s seconds, then lights up in a random team\'s colour (one of\n-- game.teams(), with the game\'s seeded rand(), so a replay picks the same\n-- teams) for params.window_s seconds. A hit (the hit capability\'s input\n-- hit.hit, with strength 0-255) of at least params.min_strength while the\n-- window is open scores params.hit_points for the window\'s team and logs\n-- target.hit with window_open = true; the first such hit closes the window\n-- unless params.multi_hit. A hit while the target is dark scores nothing and\n-- logs target.hit with window_open = false. Weaker hits are ignored. The\n-- target is armed (it reports hits) from the start of the game to its end.\n-- Owner overrides (cmd.set_owner) mean nothing here and are ignored.\n-- Screens (assets/screens/): standby while dark (with the last scoring hit),\n-- window while open; final_score at the end (the Field Box\'s built-in screen).\n\nlocal s = state.node { team = nil, left = 0, last_team = nil, hits = 0 }\nlocal timer = nil -- the timer that opens or closes the next window\nlocal tick = nil -- the per-second countdown while a window is open\nlocal running = false\n\nlocal function show()\n  if s.team then\n    ui.screen("window", { team = s.team, left = s.left })\n  else\n    ui.screen("standby", { team = s.last_team, hits = s.hits })\n  end\nend\n\nlocal open_window\n\nlocal function close_window()\n  if tick then\n    cancel(tick)\n    tick = nil\n  end\n  if timer then\n    cancel(timer)\n    timer = nil\n  end\n  s.team = nil\n  cap("ring"):off()\n  show()\n  if running then\n    timer = after(params.interval_s, open_window)\n  end\nend\n\nopen_window = function()\n  timer = nil\n  local teams = game.teams()\n  if #teams == 0 then\n    return\n  end\n  s.team = teams[rand(1, #teams)]\n  s.left = params.window_s\n  cap("ring"):fill(s.team)\n  audio.play("window")\n  show()\n  timer = after(params.window_s, close_window)\n  tick = every(1, function()\n    if s.left > 1 then\n      s.left = s.left - 1\n      show()\n    end\n  end)\nend\n\non("game.start", function()\n  if running then\n    return\n  end\n  running = true\n  cap("hit"):arm()\n  show()\n  timer = after(params.interval_s, open_window)\nend)\n\non("hit.hit", function(e)\n  local strength = tonumber(e.strength) or 0\n  if not running or strength < params.min_strength then\n    return\n  end\n  local team = s.team\n  if team == nil then\n    emit("target.hit", { window_open = false })\n    return\n  end\n  emit("target.hit", { team = team, window_open = true })\n  score.add(team, params.hit_points, "target")\n  s.last_team, s.hits = team, s.hits + 1\n  audio.play("hit")\n  if not params.multi_hit then\n    close_window()\n  end\nend)\n\non("game.end", function()\n  running = false\n  if tick then\n    cancel(tick)\n    tick = nil\n  end\n  if timer then\n    cancel(timer)\n    timer = nil\n  end\n  s.team = nil\n  cap("hit"):disarm()\n  cap("ring"):off()\n  ui.screen("final_score", {})\nend)\n',
    'assets/screens/standby.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The target is dark between windows. Data: team (the team of the last\n# scoring hit, if any) and hits (scoring hits on this target so far).\ntemplate: standby\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: panel }\n    children:\n      - type: label\n        text: TARGET\n        style: { font_size: 20, width: fill, align: center }\n  - type: spacer\n    height: fill\n  - type: label\n    text: STAND BY\n    style: { font_size: 28, color: accent }\n  - type: label\n    text: Wait for your colour\n    style: { font_size: 20, color: muted }\n  - type: label\n    text: "Last hit: {team|upper}"\n    style: { font_size: 20, color: team, visible: "{team}" }\n  - type: label\n    text: "{hits} scoring hits"\n    style: { font_size: 14, color: muted, visible: "{hits > 0}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Hit the target while it shows your colour\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
    'assets/screens/window.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A scoring window is open. Data: team (whose window it is) and left (seconds\n# until it closes).\ntemplate: window\nstyle: { background: team }\nlayout:\n  - type: spacer\n    height: fill\n  - type: label\n    text: HIT IT\n    style: { font_size: 28, color: contrast }\n  - type: label\n    text: "{team|upper}"\n    style: { font_size: 48, color: contrast }\n  - type: label\n    text: "{left} s"\n    style: { font_size: 28, color: contrast }\n  - type: spacer\n    height: fill\n',
  },
  'vip_payload': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.vip_payload\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nname: VIP / Payload\ndescription: >-\n  One team escorts its VIP, a player who shares their position, or a payload, a phone with GPS, to an\n  extraction zone; the other teams try to stop them. Reaching the zone scores and can end the game.\n  Checkpoint boxes along the way are captured as in Domination and score while a team holds them.\nroles:\n  checkpoint: { requires: [team_input], optional: [team_display, display, audio] }\n  payload:    { requires: [gps], optional: [display, audio] }\nparams:\n  vip_team:          { type: team, default: red, label: "Team that escorts the VIP and the payload" }\n  extraction:        { type: string, optional: true, max: 28, label: "Centre of the extraction zone, latitude,longitude in degrees, e.g. 38.722345,-9.139312 (empty: no extraction)" }\n  radius_m:          { type: int, min: 10, max: 1000, default: 25, label: "Radius of the extraction zone (m)" }\n  vip_points:        { type: int, min: 0, max: 1000, default: 100, label: "Points for the escorting team at the extraction" }\n  end_on_extract:    { type: bool, default: true, label: "The extraction ends the game, won by the escorting team" }\n  checkpoint_points: { type: int, min: 0, max: 1000, default: 1, label: "Points per tick for the team holding a checkpoint (0: none)" }\n  tick_s:            { type: int, min: 1, max: 600, default: 10, label: "Seconds per scoring tick of a checkpoint" }\n  capture_hold_ms:   { type: int, min: 0, max: 60000, default: 3000, label: "Hold time to capture a checkpoint (ms)" }\n  lang:              { type: string, default: pt, max: 2, label: "Language of the screens: pt or en" }\ni18n:\n  pt:\n    name: VIP / Carga\n    description: >-\n      Uma equipa escolta o seu VIP, quem partilha a sua posição, ou uma carga, um telemóvel com GPS, até\n      uma zona de extração; as outras equipas tentam impedi-lo. Chegar à zona dá pontos e pode acabar o\n      jogo. Os pontos de controlo pelo caminho capturam-se como no Domínio e dão pontos enquanto uma\n      equipa os tiver.\n    params:\n      vip_team: Equipa que escolta o VIP e a carga\n      extraction: "Centro da zona de extração, latitude,longitude em graus, ex.: 38.722345,-9.139312 (vazio: sem extração)"\n      radius_m: Raio da zona de extração (m)\n      vip_points: Pontos para a equipa que escolta, na extração\n      end_on_extract: A extração acaba o jogo, ganho pela equipa que escolta\n      checkpoint_points: "Pontos por intervalo para a equipa que tem um ponto de controlo (0: nenhum)"\n      tick_s: Segundos por intervalo de um ponto de controlo\n      capture_hold_ms: Tempo a premir para capturar um ponto de controlo (ms)\n      lang: "Língua dos ecrãs: pt ou en"\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- VIP / Payload, on each node. Two roles run this script:\n--\n-- * checkpoint: a team captures the box by holding its input, as in\n--   Domination. Boxes do not score: the controller\'s field.lua scores the\n--   holder of each checkpoint every params.tick_s seconds.\n-- * payload: an Android prop with GPS. The app gives it gps.fix (lat, lon,\n--   acc) from the phone\'s location; it checks the extraction zone itself with\n--   geo.in_zone() and emits only vip.extracted, once: positions never leave\n--   the phone (decision P4R6). Its screen shows the metres left to the zone.\n--\n-- A script does not know its role: only a role that uses gps gets gps.fix (the\n-- app sends one without lat and lon when the game starts, before the phone\'s\n-- first fix), and team inputs reach only checkpoints, so each part answers its\n-- own inputs (decision M5-5). Screens (assets/screens/): checkpoint_free,\n-- checkpoint_held, payload; final_score at the end (the Field Box\'s built-in).\n\nlocal s = state.node { owner = nil, since = 0, extracted = false }\nlocal payload = false -- set by the first gps.fix: this node is the payload\n\n-- "lat,lon" in degrees; nil when empty or unreadable (field.lua refuses those at load).\nlocal zone\ndo\n  local lat, lon =\n    string.match(params.extraction or "", "^%s*([%-+]?[%d.]+)%s*,%s*([%-+]?[%d.]+)%s*\$")\n  lat, lon = tonumber(lat), tonumber(lon)\n  if lat and lon and lat >= -90 and lat <= 90 and lon >= -180 and lon <= 180 then\n    zone = { type = "circle", lat = lat + 0.0, lon = lon + 0.0, radius_m = params.radius_m }\n  end\nend\n\nlocal function show()\n  if s.owner then\n    ui.screen("checkpoint_held", { team = s.owner, since = s.since })\n  else\n    ui.screen("checkpoint_free", {})\n  end\nend\n\nlocal function show_payload(state, metres)\n  ui.screen("payload", { team = params.vip_team, state = state, metres = metres })\nend\n\non("game.start", show)\n\n-- Checkpoints.\n\nlocal function capture(team, squad)\n  emit("zone.captured", { team = team, squad = squad, previous_team = s.owner })\n  s.owner = team\n  s.since = math.floor(game.time())\n  cap("team_display"):show(team)\n  audio.play("captured")\n  show()\nend\n\non("team_input.hold", function(e)\n  if not payload and e.team ~= s.owner and e.ms >= params.capture_hold_ms then\n    capture(e.team, e.squad)\n  end\nend)\n\n-- The GM\'s owner override: a team, or none to free the checkpoint.\non("cmd.set_owner", function(e)\n  if payload then\n    return\n  end\n  local free = e.team == nil or e.team == "" or e.team == "none"\n  if e.team == s.owner or (free and s.owner == nil) then\n    return\n  end\n  if free then\n    emit("zone.neutralized", { previous_team = s.owner })\n    s.owner = nil\n    cap("team_display"):show("none")\n    show()\n  else\n    capture(e.team)\n  end\nend)\n\n-- The payload.\n\non("gps.fix", function(e)\n  payload = true\n  if s.extracted then\n    return\n  end\n  if zone == nil then\n    return show_payload("no_zone", 0)\n  end\n  if type(e.lat) ~= "number" or type(e.lon) ~= "number" then\n    return show_payload("searching", 0)\n  end\n  -- A fix less precise than the zone\'s radius could put the payload in it by chance.\n  if type(e.acc) == "number" and e.acc > params.radius_m then\n    return show_payload("weak", math.floor(e.acc))\n  end\n  if geo.in_zone(e.lat, e.lon, zone) then\n    s.extracted = true\n    emit("vip.extracted", { team = params.vip_team })\n    audio.play("captured")\n    return show_payload("extracted", 0)\n  end\n  show_payload("moving", math.ceil(geo.distance(e.lat, e.lon, zone.lat, zone.lon) - zone.radius_m))\nend)\n\non("game.end", function()\n  ui.screen("final_score", { owner = s.owner })\nend)\n',
    'field.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- VIP / Payload, on the field controller.\n--\n-- * The VIP: the controller hands this script position.fix (player, team,\n--   role, lat, lon, acc, src) for each new position report of a player whose\n--   check-in role is vip, and to no other script (decision P4R6). A fix of the\n--   escorting team\'s VIP inside the extraction zone extracts it: vip.extracted\n--   with the player. A fix less precise than the zone\'s radius does not count.\n--   Coordinates stay here: never in an event, a log line or state.field.\n-- * The payload: its own phone checks the zone and emits vip.extracted; this\n--   script takes that as the extraction (and emits nothing more).\n-- * The extraction, once per game: params.vip_points for the escorting team,\n--   and with params.end_on_extract the game ends, won by that team.\n-- * Checkpoints: every second, the holder of each checkpoint (the boxes\' own\n--   reports, field.owner) is counted; a team that has held one for\n--   params.tick_s seconds in a row scores params.checkpoint_points, and counts\n--   again from zero.\n\nlocal fs = state.field { extracted = false, by = nil }\n\n-- "lat,lon" in degrees. A malformed one stops the game from starting, with this message.\nlocal zone\nif params.extraction ~= nil and params.extraction ~= "" then\n  local lat, lon = string.match(params.extraction, "^%s*([%-+]?[%d.]+)%s*,%s*([%-+]?[%d.]+)%s*\$")\n  lat, lon = tonumber(lat), tonumber(lon)\n  if not (lat and lon and lat >= -90 and lat <= 90 and lon >= -180 and lon <= 180) then\n    error("extraction: latitude,longitude in degrees, e.g. 38.722345,-9.139312", 0)\n  end\n  zone = { type = "circle", lat = lat + 0.0, lon = lon + 0.0, radius_m = params.radius_m }\nend\n\nlocal function extract(by, player)\n  fs.extracted = true\n  fs.by = by\n  if by == "vip" then\n    emit("vip.extracted", { team = params.vip_team, player = player })\n  end\n  if params.vip_points > 0 then\n    score.add(params.vip_team, params.vip_points, "extraction")\n  end\n  if params.end_on_extract then\n    game.win(params.vip_team)\n  end\nend\n\non("position.fix", function(e)\n  if fs.extracted or zone == nil or e.role ~= "vip" or e.team ~= params.vip_team then\n    return\n  end\n  if type(e.lat) ~= "number" or type(e.lon) ~= "number" then\n    return\n  end\n  if type(e.acc) == "number" and e.acc > params.radius_m then\n    return\n  end\n  if geo.in_zone(e.lat, e.lon, zone) then\n    extract("vip", type(e.player) == "string" and e.player or nil)\n  end\nend)\n\n-- From the payload prop, which checked the zone itself.\non("vip.extracted", function(e)\n  if not fs.extracted and e.team == params.vip_team then\n    extract("payload")\n  end\nend)\n\nlocal held = {} -- checkpoint node id -> { team, s }\n\nevery(1, function()\n  if params.checkpoint_points <= 0 then\n    return\n  end\n  for _, n in ipairs(field.nodes("checkpoint")) do\n    local owner = field.owner(n.id)\n    local h = held[n.id]\n    if owner == nil then\n      held[n.id] = nil\n    elseif h == nil or h.team ~= owner then\n      held[n.id] = { team = owner, s = 0 }\n    else\n      h.s = h.s + 1\n      if h.s >= params.tick_s then\n        h.s = 0\n        score.add(owner, params.checkpoint_points, "checkpoint")\n      end\n    end\n  end\nend)\n',
    'assets/screens/checkpoint_free.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# Nobody holds the checkpoint. No data; the hold time comes from the game\'s\n# parameters. Texts in params.lang (pt or en).\ntemplate: checkpoint_free\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: panel }\n    children:\n      - type: label\n        text: PONTO DE CONTROLO\n        style: { font_size: 20, width: fill, align: center, visible: "{params.lang != \'en\'}" }\n      - type: label\n        text: CHECKPOINT\n        style: { font_size: 20, width: fill, align: center, visible: "{params.lang == \'en\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: MANTÉM PREMIDO\n    style: { font_size: 28, color: accent, visible: "{params.lang != \'en\'}" }\n  - type: label\n    text: HOLD TO CAPTURE\n    style: { font_size: 28, color: accent, visible: "{params.lang == \'en\'}" }\n  - type: label\n    text: "o botão {params.capture_hold_ms / 1000} s para capturar"\n    style: { font_size: 20, color: muted, visible: "{params.lang != \'en\'}" }\n  - type: label\n    text: "Hold your button for {params.capture_hold_ms / 1000} s"\n    style: { font_size: 20, color: muted, visible: "{params.lang == \'en\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Ninguém tem este ponto\n    style:\n      font_size: 14\n      color: muted\n      visible: "{params.lang != \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: Nobody holds this checkpoint\n    style:\n      font_size: 14\n      color: muted\n      visible: "{params.lang == \'en\'}"\n      padding: { bottom: 10 }\n',
    'assets/screens/checkpoint_held.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A team holds the checkpoint. Data: team, since (game time of the capture,\n# in seconds). The box does not score: the controller does, while it is held.\n# Texts in params.lang (pt or en).\ntemplate: checkpoint_held\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: team }\n    children:\n      - type: label\n        text: PONTO CAPTURADO\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{params.lang != \'en\'}" }\n      - type: label\n        text: CHECKPOINT HELD\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{params.lang == \'en\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{team|upper}"\n    style: { font_size: 48, color: team }\n  - type: label\n    text: "desde {since|clock}"\n    style: { font_size: 20, color: muted, visible: "{params.lang != \'en\'}" }\n  - type: label\n    text: "held since {since|clock}"\n    style: { font_size: 20, color: muted, visible: "{params.lang == \'en\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Mantém o teu botão para o tomar\n    style:\n      font_size: 14\n      color: muted\n      visible: "{params.lang != \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: Hold your button to take it over\n    style:\n      font_size: 14\n      color: muted\n      visible: "{params.lang == \'en\'}"\n      padding: { bottom: 10 }\n',
    'assets/screens/payload.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The payload prop (a phone with GPS). Data: team (the escorting team),\n# state (searching: no fix yet; weak: the fix is less precise than the zone,\n# metres is its accuracy; no_zone: the game has no extraction zone; moving:\n# metres is the distance to the zone\'s edge; extracted), metres. Texts in\n# params.lang (pt or en). Nothing here says where the zone or the phone is.\ntemplate: payload\nstyle: { background: "{state == \'extracted\' && team || \'background\'}" }\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: team }\n    children:\n      - type: label\n        text: CARGA\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{params.lang != \'en\'}" }\n      - type: label\n        text: PAYLOAD\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{params.lang == \'en\'}" }\n  - type: spacer\n    height: fill\n  - type: icon\n    icon: gps\n    style: { font_size: 48, color: muted, visible: "{state == \'searching\' || state == \'weak\'}" }\n  - type: label\n    text: "{metres} m"\n    style: { font_size: 48, color: accent, visible: "{state == \'moving\'}" }\n  - type: label\n    text: até à zona de extração\n    style: { font_size: 20, color: muted, visible: "{state == \'moving\' && params.lang != \'en\'}" }\n  - type: label\n    text: to the extraction zone\n    style: { font_size: 20, color: muted, visible: "{state == \'moving\' && params.lang == \'en\'}" }\n  - type: label\n    text: À procura de GPS\n    style: { font_size: 28, visible: "{state == \'searching\' && params.lang != \'en\'}" }\n  - type: label\n    text: Looking for GPS\n    style: { font_size: 28, visible: "{state == \'searching\' && params.lang == \'en\'}" }\n  - type: label\n    text: "GPS fraco ({metres} m)"\n    style: { font_size: 28, color: orange, visible: "{state == \'weak\' && params.lang != \'en\'}" }\n  - type: label\n    text: "Weak GPS ({metres} m)"\n    style: { font_size: 28, color: orange, visible: "{state == \'weak\' && params.lang == \'en\'}" }\n  - type: label\n    text: Sem zona de extração\n    style: { font_size: 28, color: muted, visible: "{state == \'no_zone\' && params.lang != \'en\'}" }\n  - type: label\n    text: No extraction zone\n    style: { font_size: 28, color: muted, visible: "{state == \'no_zone\' && params.lang == \'en\'}" }\n  - type: icon\n    icon: ok\n    style: { font_size: 48, color: contrast, visible: "{state == \'extracted\'}" }\n  - type: label\n    text: EXTRAÇÃO CONCLUÍDA\n    style: { font_size: 20, color: contrast, visible: "{state == \'extracted\' && params.lang != \'en\'}" }\n  - type: label\n    text: EXTRACTED\n    style: { font_size: 28, color: contrast, visible: "{state == \'extracted\' && params.lang == \'en\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Leva-me à zona de extração\n    style:\n      font_size: 14\n      color: muted\n      visible: "{state != \'extracted\' && params.lang != \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: Take me to the extraction zone\n    style:\n      font_size: 14\n      color: muted\n      visible: "{state != \'extracted\' && params.lang == \'en\'}"\n      padding: { bottom: 10 }\n',
  },
};
